INSERT INTO _n1_b7_guard_0122(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2026-12-24' AND '2027-01-06' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b7_words_0122(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3001','2026-12-24','概論','がいろん','개론; 전체 내용을 간추린 설명','ある分野の全体像や基本事項をまとめて述べたもの。','初学者向けの概論を読んでから専門書に進んだ。','초보자용 개론을 읽은 뒤 전문 서적으로 넘어갔다.'),
('n1-3002','2026-12-24','規律','きりつ','규율; 질서를 유지하기 위한 규칙','集団の秩序を保つために守るべき決まり。','組織の規律を保ちながら、柔軟な働き方も認める。','조직의 규율을 유지하면서 유연한 근무 방식도 인정한다.'),
('n1-3003','2026-12-24','系統','けいとう','계통; 체계; 같은 갈래','一定の関係でつながるまとまりや体系。','障害が発生した系統を切り離して影響を抑えた。','장애가 발생한 계통을 분리해 영향을 줄였다.'),
('n1-3004','2026-12-24','公務','こうむ','공무; 국가나 지방자치단체의 업무','国や地方公共団体が行う公の仕事。','公務に携わる者には高い倫理意識が求められる。','공무에 종사하는 사람에게는 높은 윤리 의식이 요구된다.'),
('n1-3005','2026-12-24','性質','せいしつ','성질; 사물이나 사람의 고유한 특성','物事や人に備わっている固有の特徴。','この素材は熱を通しにくい性質を持っている。','이 소재는 열을 잘 전달하지 않는 성질을 지니고 있다.'),
('n1-3006','2026-12-24','性能','せいのう','성능; 기계 등이 발휘할 수 있는 능력','機械や装置などが発揮できる能力。','新型端末は処理性能と省電力性の両方が向上した。','신형 단말기는 처리 성능과 절전성이 모두 향상되었다.'),
('n1-3007','2026-12-24','専制','せんせい','전제; 권력을 독점하여 마음대로 지배함','一人または少数者が権力を独占して支配すること。','権力の集中が専制につながらない仕組みが必要だ。','권력 집중이 전제로 이어지지 않도록 하는 장치가 필요하다.'),
('n1-3008','2026-12-24','対策','たいさく','대책; 문제에 대응하기 위한 방법','問題や事態に対応するための方法や手段。','被害を最小限に抑えるため、早急な対策を講じた。','피해를 최소화하기 위해 신속히 대책을 마련했다.'),
('n1-3009','2026-12-24','体制','たいせい','체제; 조직적으로 대응하는 구조','組織や社会が機能するための仕組みや構成。','緊急時にも対応できる支援体制を整えた。','긴급 상황에도 대응할 수 있는 지원 체제를 갖추었다.'),
('n1-3010','2026-12-24','能率','のうりつ','능률; 일정 시간에 이루는 작업의 효율','一定の時間内に仕事を成し遂げる割合や効率。','手順を見直した結果、作業の能率が大幅に上がった。','절차를 재검토한 결과 작업 능률이 크게 올랐다.'),
('n1-3011','2026-12-24','評論','ひょうろん','평론; 가치나 문제점을 분석하여 논함','物事の価値や問題点を分析し、論じること。','その評論は作品の社会的背景を鋭く分析している。','그 평론은 작품의 사회적 배경을 날카롭게 분석하고 있다.'),
('n1-3012','2026-12-24','不規則','ふきそく','불규칙; 일정한 규칙이 없음','一定の規則や周期に従っていないこと。','不規則な勤務が続き、生活のリズムが崩れた。','불규칙한 근무가 계속되어 생활 리듬이 무너졌다.'),
('n1-3013','2026-12-24','観測','かんそく','관측; 현상이나 변화를 살펴 측정함','自然現象や変化を継続的に観察し、測定すること。','衛星から台風の進路を観測している。','위성으로 태풍의 진로를 관측하고 있다.'),
('n1-3014','2026-12-24','観念','かんねん','관념; 어떤 대상에 대해 마음속에 형성된 생각','物事について心に抱く考えや意識。','従来の固定観念にとらわれず、制度を見直すべきだ。','기존의 고정관념에 얽매이지 말고 제도를 재검토해야 한다.'),
('n1-3015','2026-12-24','催促','さいそく','재촉; 빨리 처리하도록 독촉함','物事を早く行うよう相手に求めること。','返事がなかったため、担当者に確認を催促した。','답변이 없어서 담당자에게 확인을 재촉했다.'),
('n1-3016','2026-12-24','侵入','しんにゅう','침입; 허가 없이 안으로 들어감','他の領域や建物などへ不法または無断で入り込むこと。','不審者の侵入を防ぐため、入口の警備を強化した。','수상한 사람의 침입을 막기 위해 입구 경비를 강화했다.'),
('n1-3017','2026-12-24','制作','せいさく','제작; 예술 작품이나 콘텐츠를 만듦','芸術作品や映像などを作ること。','地域の歴史を紹介する映像を制作した。','지역의 역사를 소개하는 영상을 제작했다.'),
('n1-3018','2026-12-24','抽象','ちゅうしょう','추상; 공통 성질을 뽑아 개념화함','個々の事物から共通する性質を取り出して考えること。','抽象的な説明だけでは、具体的な手順が伝わりにくい。','추상적인 설명만으로는 구체적인 절차가 전달되기 어렵다.'),
('n1-3019','2026-12-24','的確','てきかく','적확; 정확하고 핵심에 들어맞음','判断や表現が正確で、要点を外していないこと。','状況を把握し、的確な指示を出す必要がある。','상황을 파악해 정확한 지시를 내릴 필요가 있다.'),
('n1-3020','2026-12-24','統一','とういつ','통일; 여러 가지를 하나의 기준으로 맞춤','ばらばらなものを一つの方針や形式にまとめること。','文書の表記を社内基準に合わせて統一した。','문서 표기를 사내 기준에 맞춰 통일했다.'),
('n1-3021','2026-12-25','統計','とうけい','통계; 자료를 수집·정리하여 수치로 나타낸 것','多数の資料を集め、整理して数量的に示したもの。','最新の統計によると、利用者数は増加傾向にある。','최신 통계에 따르면 이용자 수는 증가 추세이다.'),
('n1-3022','2026-12-25','免税','めんぜい','면세; 세금 부과를 면제함','税金の全部または一部を免除すること。','一定の条件を満たせば、購入品が免税の対象になる。','일정 조건을 충족하면 구매품이 면세 대상이 된다.'),
('n1-3023','2026-12-25','消極的','しょうきょくてき','소극적; 스스로 적극적으로 나서지 않는 모습','自分から進んで行動しようとしないさま。','失敗を恐れて消極的になると、改善の機会を逃してしまう。','실패를 두려워해 소극적이 되면 개선할 기회를 놓치게 된다.'),
('n1-3024','2026-12-25','比較的','ひかくてき','비교적; 다른 것과 비교해 보아 상대적으로','他と比べると、ある傾向が認められるさま。','この地域は冬でも比較的暖かい。','이 지역은 겨울에도 비교적 따뜻하다.'),
('n1-3025','2026-12-25','確率','かくりつ','확률; 어떤 일이 일어날 가능성을 나타내는 수치','ある事象が起こる可能性を数値で表したもの。','標本数が少ないため、結果が偶然である確率も考慮した。','표본 수가 적어서 결과가 우연일 확률도 고려했다.'),
('n1-3026','2026-12-25','強化','きょうか','강화; 더 강하고 효과적으로 만듦','能力や体制などをさらに強くすること。','情報漏えいを防ぐため、認証機能を強化した。','정보 유출을 막기 위해 인증 기능을 강화했다.'),
('n1-3027','2026-12-25','意義','いぎ','의의; 어떤 일이나 행위가 지닌 가치와 중요성','物事が持つ価値や重要な意味。','この調査には地域の課題を明らかにする意義がある。','이 조사에는 지역의 과제를 밝힌다는 의의가 있다.'),
('n1-3028','2026-12-25','応用','おうよう','응용; 원리나 지식을 다른 상황에 적용함','知識や原理を別の事柄に当てはめて利用すること。','基礎理論を実際の開発に応用する。','기초 이론을 실제 개발에 응용한다.'),
('n1-3029','2026-12-25','過失','かしつ','과실; 주의를 게을리하여 생긴 잘못','注意を怠ったために生じた誤りや損害。','事故が重大な過失によるものか調査が進められている。','사고가 중대한 과실로 인한 것인지 조사가 진행되고 있다.'),
('n1-3030','2026-12-25','基準','きじゅん','기준; 판단하거나 비교할 때 근거가 되는 것','判断や比較のよりどころとなる尺度。','審査基準を明確にし、手続きの透明性を高めた。','심사 기준을 명확히 하여 절차의 투명성을 높였다.'),
('n1-3031','2026-12-25','原理','げんり','원리; 현상이나 작용의 근본 법칙','物事が成り立つ根本的な法則や仕組み。','装置が動く原理を理解してから操作を始めた。','장치가 작동하는 원리를 이해한 뒤 조작을 시작했다.'),
('n1-3032','2026-12-25','公害','こうがい','공해; 산업 활동 등으로 환경과 주민에게 생기는 피해','産業活動などによって環境や住民に生じる社会的な害。','工場排水による公害を防ぐため規制が強化された。','공장 폐수로 인한 공해를 막기 위해 규제가 강화되었다.'),
('n1-3033','2026-12-25','功績','こうせき','공적; 어떤 분야에 기여한 뛰어난 성과','社会や組織に貢献した優れた成果。','長年の研究上の功績が認められ、賞が贈られた。','오랜 연구 공적을 인정받아 상이 수여되었다.'),
('n1-3034','2026-12-25','合理','ごうり','합리; 이치나 논리에 맞음','道理や論理にかなっていること。','限られた予算を合理的に配分する必要がある。','한정된 예산을 합리적으로 배분할 필요가 있다.'),
('n1-3035','2026-12-25','効力','こうりょく','효력; 효과를 발휘하는 힘이나 법적 유효성','効果を及ぼす力、または法律上の有効性。','この契約は署名した日から効力を生じる。','이 계약은 서명한 날부터 효력이 발생한다.'),
('n1-3036','2026-12-25','実感','じっかん','실감; 실제로 그렇다고 느끼는 감각','実際に経験して、本当にそうだと感じること。','利用者の声を聞き、改善の効果を実感した。','이용자의 목소리를 듣고 개선 효과를 실감했다.'),
('n1-3037','2026-12-25','実績','じっせき','실적; 실제로 이룬 성과','実際に成し遂げた成果や成績。','過去の実績だけでなく、今後の可能性も評価する。','과거 실적뿐 아니라 앞으로의 가능성도 평가한다.'),
('n1-3038','2026-12-25','実用','じつよう','실용; 실제 생활이나 업무에 사용함','実際の生活や仕事に役立てて使うこと。','研究成果を実用に移すには安全性の検証が欠かせない。','연구 성과를 실용화하려면 안전성 검증이 필수적이다.'),
('n1-3039','2026-12-25','圧縮','あっしゅく','압축; 부피나 데이터의 크기를 줄임','圧力を加えて小さくすること、またはデータ量を減らすこと。','送信前に画像データを圧縮して容量を減らした。','전송 전에 이미지 데이터를 압축해 용량을 줄였다.'),
('n1-3040','2026-12-25','改正','かいせい','개정; 법률이나 규칙을 고쳐 바꿈','法律や規則などを改めて正すこと。','社会の変化に合わせて関連法が改正された。','사회 변화에 맞춰 관련 법률이 개정되었다.');
INSERT INTO _n1_b7_words_0122(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3041','2026-12-26','過半数','かはんすう','과반수; 전체의 절반을 넘는 수','全体の半分を超える数。','議案は出席者の過半数の賛成で可決された。','의안은 출석자 과반수의 찬성으로 가결되었다.'),
('n1-3042','2026-12-26','移転','いてん','이전; 장소나 권리 등을 다른 곳으로 옮김','場所や権利などを別の所へ移すこと。','本社の移転に伴い、住所と電話番号が変わった。','본사 이전에 따라 주소와 전화번호가 바뀌었다.'),
('n1-3043','2026-12-26','有無','うむ','유무; 있음과 없음','あることと、ないこと。','経験の有無にかかわらず応募することができる。','경험 유무와 관계없이 지원할 수 있다.'),
('n1-3044','2026-12-26','解説','かいせつ','해설; 내용을 알기 쉽게 설명함','内容や背景を分かりやすく説明すること。','専門家が制度変更の要点を詳しく解説した。','전문가가 제도 변경의 요점을 자세히 해설했다.'),
('n1-3045','2026-12-26','改造','かいぞう','개조; 기존 구조를 고쳐 다른 형태나 기능으로 만듦','既存の構造を変えて、別の形や機能に作り替えること。','古い建物を改造して交流施設として活用している。','오래된 건물을 개조해 교류 시설로 활용하고 있다.'),
('n1-3046','2026-12-26','解放','かいほう','해방; 속박이나 제한에서 벗어나게 함','束縛や制限から自由にすること。','長時間の緊張から解放され、ようやく安心した。','오랜 긴장에서 해방되어 마침내 안심했다.'),
('n1-3047','2026-12-26','拡充','かくじゅう','확충; 규모나 내용을 넓혀 충실하게 함','規模や内容を広げ、より充実させること。','自治体は子育て支援制度の拡充を進めている。','지자체는 육아 지원 제도의 확충을 추진하고 있다.'),
('n1-3048','2026-12-26','学術','がくじゅつ','학술; 전문적인 학문과 연구','専門的な学問や研究に関すること。','研究成果は国際的な学術誌に掲載された。','연구 성과는 국제 학술지에 게재되었다.'),
('n1-3049','2026-12-26','拡張','かくちょう','확장; 범위나 규모, 기능을 넓힘','範囲や規模、機能などを広げること。','利用者の増加に備えてサーバー容量を拡張した。','이용자 증가에 대비해 서버 용량을 확장했다.'),
('n1-3050','2026-12-26','可決','かけつ','가결; 의안이 찬성을 얻어 통과됨','議案が賛成を得て成立すること。','予算案は賛成多数で可決された。','예산안은 찬성 다수로 가결되었다.'),
('n1-3051','2026-12-26','過剰','かじょう','과잉; 필요한 정도를 지나치게 넘음','必要な程度を超えて多すぎること。','過剰な包装を減らす取り組みが広がっている。','과잉 포장을 줄이려는 움직임이 확산되고 있다.'),
('n1-3052','2026-12-26','課税','かぜい','과세; 세금을 부과함','税金を割り当てて負担させること。','所得に応じて課税される仕組みになっている。','소득에 따라 과세되는 구조로 되어 있다.'),
('n1-3053','2026-12-26','仮定','かてい','가정; 사실인지 확정되지 않은 것을 임시로 설정함','事実かどうか未確定のことを、ひとまずそうだと定めること。','最悪の事態を仮定して避難計画を作成した。','최악의 상황을 가정해 대피 계획을 작성했다.'),
('n1-3054','2026-12-26','過程','かてい','과정; 일이 진행되어 결과에 이르는 경로','物事が進行して結果に至るまでの道筋。','結論だけでなく、そこに至る過程も記録しておく。','결론뿐 아니라 거기에 이르는 과정도 기록해 둔다.'),
('n1-3055','2026-12-26','為替','かわせ','환; 환율; 현금을 직접 보내지 않고 결제하는 제도','現金を直接送らずに決済する仕組み。また、通貨の交換比率。','為替の変動が輸入価格に大きな影響を与えた。','환율 변동이 수입 가격에 큰 영향을 주었다.'),
('n1-3056','2026-12-26','間隔','かんかく','간격; 둘 사이의 거리나 시간의 차이','二つの物や時点の間にある距離や時間。','十分な間隔を空けて座席を配置した。','충분한 간격을 두고 좌석을 배치했다.'),
('n1-3057','2026-12-26','間接','かんせつ','간접; 다른 것을 사이에 두고 관계함','他のものを間に置いて関係すること。','その政策は雇用にも間接的な影響を及ぼした。','그 정책은 고용에도 간접적인 영향을 미쳤다.'),
('n1-3058','2026-12-26','官庁','かんちょう','관청; 국가의 행정 사무를 담당하는 기관','国の行政事務を担当する機関。','関係する官庁が共同で調査を実施した。','관련 관청이 공동으로 조사를 실시했다.'),
('n1-3059','2026-12-26','期限','きげん','기한; 어떤 일을 마쳐야 하는 정해진 시점','物事を終えなければならないと定められた時点。','申請期限を過ぎると受け付けてもらえない。','신청 기한을 넘기면 접수해 주지 않는다.'),
('n1-3060','2026-12-26','基礎','きそ','기초; 사물의 토대가 되는 기본 부분','物事の土台となる基本的な部分。','基礎を十分に理解してから応用問題に進む。','기초를 충분히 이해한 뒤 응용 문제로 넘어간다.'),
('n1-3061','2026-12-27','基盤','きばん','기반; 활동이나 발전을 떠받치는 토대','活動や発展を支える土台。','安定した通信基盤の整備が欠かせない。','안정적인 통신 기반의 정비가 필수적이다.'),
('n1-3062','2026-12-27','境界','きょうかい','경계; 영역과 영역을 가르는 선이나 지점','領域と領域とを分ける線や場所。','現実と虚構の境界が曖昧な作品だ。','현실과 허구의 경계가 모호한 작품이다.'),
('n1-3063','2026-12-27','教養','きょうよう','교양; 폭넓은 지식과 판단력을 기르는 소양','幅広い知識を身につけ、人格や判断力を高める素養。','専門知識だけでなく幅広い教養も求められる。','전문 지식뿐 아니라 폭넓은 교양도 요구된다.'),
('n1-3064','2026-12-27','区域','くいき','구역; 일정한 기준으로 나눈 범위','一定の基準で区切られた範囲。','この区域では建物の高さが制限されている。','이 구역에서는 건물 높이가 제한되어 있다.'),
('n1-3065','2026-12-27','区分','くぶん','구분; 기준에 따라 나누는 일이나 그 범주','基準に従って分けること、またはその分けられた範囲。','所得の区分によって必要な書類が異なる。','소득 구분에 따라 필요한 서류가 다르다.'),
('n1-3066','2026-12-27','形式','けいしき','형식; 일정하게 정해진 방식이나 모양','物事を行う際の決まった方式や形。','報告書は指定された形式で提出してください。','보고서는 지정된 형식으로 제출해 주세요.'),
('n1-3067','2026-12-27','継続','けいぞく','계속; 이전부터 해 오던 일을 이어감','以前から行っていることをそのまま続けること。','支援を継続するには安定した財源が必要だ。','지원을 계속하려면 안정적인 재원이 필요하다.'),
('n1-3068','2026-12-27','激増','げきぞう','격증; 수량이 급격히 늘어남','数量が急激に増えること。','問い合わせが激増し、窓口の対応が追いつかない。','문의가 급증해 창구 대응이 따라가지 못한다.'),
('n1-3069','2026-12-27','気配','けはい','기미; 어떤 일이 일어나려는 낌새나 분위기','何かが起こりそうな様子や、そこに存在する感じ。','景気が回復する気配はまだ見られない。','경기가 회복될 기미는 아직 보이지 않는다.'),
('n1-3070','2026-12-27','謙虚','けんきょ','겸허; 자신을 내세우지 않고 남의 의견을 받아들이는 태도','自分を偉いと思わず、素直に他人の意見を受け入れるさま。','批判にも謙虚に耳を傾ける姿勢が大切だ。','비판에도 겸허하게 귀를 기울이는 자세가 중요하다.'),
('n1-3071','2026-12-27','原稿','げんこう','원고; 발표나 출판을 위해 작성한 글','発表や印刷のために書いた文章。','締め切りまでに論文の原稿を完成させた。','마감일까지 논문 원고를 완성했다.'),
('n1-3072','2026-12-27','原始','げんし','원시; 사물이나 사회의 가장 처음 단계','物事や社会が発達する前の、最も初期の状態。','原始社会の暮らしを遺跡から推測する。','원시 사회의 생활을 유적을 통해 추측한다.'),
('n1-3073','2026-12-27','厳重','げんじゅう','엄중; 매우 엄격하고 빈틈이 없음','非常に厳しく、注意が行き届いているさま。','機密資料は厳重に管理されている。','기밀 자료는 엄중하게 관리되고 있다.'),
('n1-3074','2026-12-27','謙遜','けんそん','겸손; 자신의 능력이나 가치를 낮추어 말함','自分の能力や価値を控えめに評価して言うこと。','彼は謙遜しているが、実際には高い技術を持っている。','그는 겸손하게 말하지만 실제로는 높은 기술을 지니고 있다.'),
('n1-3075','2026-12-27','公共','こうきょう','공공; 사회 전체 또는 여러 사람이 함께 관계되는 것','社会全体や多くの人々に共通して関わること。','公共の利益と個人の権利を両立させる必要がある。','공공의 이익과 개인의 권리를 양립시킬 필요가 있다.'),
('n1-3076','2026-12-27','公式','こうしき','공식; 정식으로 인정된 것; 계산식','公に認められた正式なもの。また、計算の法則を示す式。','調査結果は来週、公式に発表される予定だ。','조사 결과는 다음 주 공식적으로 발표될 예정이다.'),
('n1-3077','2026-12-27','口実','こうじつ','구실; 실제 이유를 감추기 위해 내세우는 핑계','本当の理由を隠すために表向きに用いる理由。','忙しさを口実にして問題を先送りしてはいけない。','바쁘다는 것을 구실로 문제를 미뤄서는 안 된다.'),
('n1-3078','2026-12-27','公正','こうせい','공정; 치우침 없이 올바르고 공평함','偏りがなく、正しく公平であること。','採用では公正な評価基準を設けるべきだ。','채용에서는 공정한 평가 기준을 마련해야 한다.'),
('n1-3079','2026-12-27','構造','こうぞう','구조; 여러 부분이 결합된 짜임새','複数の部分が組み合わさってできた仕組み。','問題の構造を分析し、根本的な原因を探った。','문제의 구조를 분석해 근본적인 원인을 찾았다.'),
('n1-3080','2026-12-27','肯定','こうてい','긍정; 옳거나 사실이라고 인정함','正しい、または事実であると認めること。','相手の意見を全面的に肯定したわけではない。','상대방의 의견을 전적으로 긍정한 것은 아니다.');
INSERT INTO _n1_b7_words_0122(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3081','2026-12-28','公表','こうひょう','공표; 여러 사람에게 공식적으로 알림','内容を広く公式に知らせること。','調査結果は来月公表される予定だ。','조사 결과는 다음 달 공표될 예정이다.'),
('n1-3082','2026-12-28','項目','こうもく','항목; 내용을 나눈 각각의 사항','内容をいくつかに分けた、それぞれの事項。','申請書の必須項目をすべて入力してください。','신청서의 필수 항목을 모두 입력해 주세요.'),
('n1-3083','2026-12-28','国籍','こくせき','국적; 특정 국가의 구성원인 법적 자격','特定の国の構成員であることを示す法的な資格。','採用では国籍を理由に不当に差別してはならない。','채용에서는 국적을 이유로 부당하게 차별해서는 안 된다.'),
('n1-3084','2026-12-28','個体','こたい','개체; 독립된 하나의 생물체나 물체','独立して存在する一つの生物体や物体。','同じ種類でも個体によって特徴が異なる。','같은 종류라도 개체에 따라 특징이 다르다.'),
('n1-3085','2026-12-28','古典','こてん','고전; 오랫동안 가치를 인정받아 온 작품','長い年月にわたって価値を認められてきた作品。','古典を現代の視点から読み直す授業を受けた。','고전을 현대적 관점에서 다시 읽는 수업을 들었다.'),
('n1-3086','2026-12-28','再三','さいさん','재삼; 여러 차례 거듭하여','同じことを何度も繰り返すさま。','再三注意したにもかかわらず、同じ誤りが起きた。','여러 차례 주의했음에도 같은 오류가 발생했다.'),
('n1-3087','2026-12-28','索引','さくいん','색인; 필요한 내용을 찾도록 정리한 목록','必要な語や事項を探せるように整理した一覧。','巻末の索引を使って関連する用語を調べた。','책 뒤의 색인을 이용해 관련 용어를 찾아봤다.'),
('n1-3088','2026-12-28','削除','さくじょ','삭제; 글이나 데이터를 지워 없앰','文章やデータなどを消して取り除くこと。','不要な個人情報を記録から削除した。','불필요한 개인정보를 기록에서 삭제했다.'),
('n1-3089','2026-12-28','作成','さくせい','작성; 문서나 자료 등을 만들어 완성함','文書や資料などを作り上げること。','調査結果を基に報告書を作成した。','조사 결과를 바탕으로 보고서를 작성했다.'),
('n1-3090','2026-12-28','自衛','じえい','자위; 스스로를 지키고 방어함','外部からの危険に対して自分を守ること。','危険を避けるための自衛手段を身につける。','위험을 피하기 위한 자위 수단을 익힌다.'),
('n1-3091','2026-12-28','自治','じち','자치; 지역이나 단체가 스스로 다스림','地域や団体が自らの責任で運営し、治めること。','住民参加による地方自治の充実が求められている。','주민 참여를 통한 지방 자치의 충실화가 요구되고 있다.'),
('n1-3092','2026-12-28','執筆','しっぴつ','집필; 글이나 책을 씀','文章や書物を書くこと。','専門家が制度の解説記事を執筆した。','전문가가 제도 해설 기사를 집필했다.'),
('n1-3093','2026-12-28','指定','してい','지정; 특정한 대상이나 조건을 정해 가리킴','特定の物や条件を定めて示すこと。','指定された日時までに書類を提出してください。','지정된 날짜와 시간까지 서류를 제출해 주세요.'),
('n1-3094','2026-12-28','地盤','じばん','지반; 건축물 등을 지탱하는 땅; 활동의 기반','建物などを支える土地。また、活動を支える基礎。','建設前に地盤の強度を詳しく調査した。','건설 전에 지반의 강도를 자세히 조사했다.'),
('n1-3095','2026-12-28','紙幣','しへい','지폐; 종이로 만든 화폐','紙で作られた通貨。','新しい紙幣には高度な偽造防止技術が使われている。','새 지폐에는 고도의 위조 방지 기술이 사용되고 있다.'),
('n1-3096','2026-12-28','社説','しゃせつ','사설; 신문사가 견해를 밝히는 논설','新聞社が重要な問題について意見を示す論説。','社説は政府の対応の遅れを厳しく批判した。','사설은 정부 대응의 지연을 엄격히 비판했다.'),
('n1-3097','2026-12-28','修繕','しゅうぜん','수선; 망가진 부분을 고쳐 원상태로 만듦','壊れたり傷んだりした部分を直すこと。','老朽化した施設を計画的に修繕する。','노후화된 시설을 계획적으로 수선한다.'),
('n1-3098','2026-12-28','重点','じゅうてん','중점; 가장 중요하게 여겨 힘을 두는 부분','特に重要だとして力を入れるところ。','今年度は人材育成に重点を置く方針だ。','올해는 인재 육성에 중점을 둘 방침이다.'),
('n1-3099','2026-12-28','就任','しゅうにん','취임; 새로운 직책을 맡음','新しい役職や地位に就くこと。','新しい社長は来月正式に就任する。','새 사장은 다음 달 정식으로 취임한다.'),
('n1-3100','2026-12-28','重役','じゅうやく','중역; 회사에서 중요한 직책을 맡은 임원','会社で重要な地位にある役員。','事業計画は重役会議で慎重に検討された。','사업 계획은 중역 회의에서 신중하게 검토되었다.'),
('n1-3101','2026-12-29','縮小','しゅくしょう','축소; 규모나 범위를 줄임','規模や範囲を小さくすること。','需要の減少を受けて生産規模を縮小した。','수요 감소에 따라 생산 규모를 축소했다.'),
('n1-3102','2026-12-29','循環','じゅんかん','순환; 일정한 경로를 따라 되풀이해 돎','一定の経路を巡り、再び元に戻ること。','資源を循環させる仕組みづくりが重要だ。','자원을 순환시키는 구조를 만드는 것이 중요하다.'),
('n1-3103','2026-12-29','順序','じゅんじょ','순서; 일을 진행하거나 배열하는 차례','物事を進めたり並べたりする際の決まった次第。','作業は説明書に記載された順序で行ってください。','작업은 설명서에 적힌 순서대로 진행해 주세요.'),
('n1-3104','2026-12-29','純粋','じゅんすい','순수; 다른 것이 섞이지 않음; 사심이 없음','他のものが混じっていないこと。また、私欲がないさま。','彼は純粋な好奇心から研究を始めた。','그는 순수한 호기심으로 연구를 시작했다.'),
('n1-3105','2026-12-29','焦点','しょうてん','초점; 관심이나 논의가 집중되는 중심','注意や議論が集中する中心点。','議論の焦点は費用負担の公平性に移った。','논의의 초점은 비용 부담의 공정성으로 옮겨갔다.'),
('n1-3106','2026-12-29','消耗','しょうもう','소모; 사용하여 줄어들거나 기력이 쇠함','使うことで減ること。また、体力や精神力が衰えること。','長時間の交渉で双方とも精神的に消耗した。','장시간 협상으로 양측 모두 정신적으로 소모되었다.'),
('n1-3107','2026-12-29','省略','しょうりゃく','생략; 일부를 줄이거나 빼버림','文章や手順などの一部を短くしたり省いたりすること。','繰り返しとなる説明は省略した。','반복되는 설명은 생략했다.'),
('n1-3108','2026-12-29','自然科学','しぜんかがく','자연과학; 자연 현상을 연구하는 학문','自然界の現象や法則を研究する学問。','自然科学では観測と実験が重要な役割を果たす。','자연과학에서는 관측과 실험이 중요한 역할을 한다.'),
('n1-3109','2026-12-29','社会科学','しゃかいかがく','사회과학; 사회 현상과 제도를 연구하는 학문','社会の現象や制度、人間関係を研究する学問。','社会科学の視点から人口減少の要因を分析する。','사회과학의 관점에서 인구 감소의 요인을 분석한다.'),
('n1-3110','2026-12-29','人文科学','じんぶんかがく','인문과학; 인간의 사상·문화·역사를 연구하는 학문','人間の思想、文化、歴史などを研究する学問。','人文科学の研究では文献の解釈が重視される。','인문과학 연구에서는 문헌 해석이 중시된다.'),
('n1-3111','2026-12-29','総理大臣','そうりだいじん','총리대신; 일본 내각의 수장','日本の内閣を代表し、行政を統括する長。','総理大臣は国会で新しい政策方針を説明した。','총리대신은 국회에서 새로운 정책 방침을 설명했다.'),
('n1-3112','2026-12-29','引力','いんりょく','인력; 물체끼리 서로 끌어당기는 힘','物体同士が互いに引き合う力。','地球の引力によって物体は地面に落下する。','지구의 인력으로 물체는 지면에 떨어진다.'),
('n1-3113','2026-12-29','学力','がくりょく','학력; 학습을 통해 얻은 지식과 능력','学習によって身につけた知識や能力。','家庭環境による学力の格差が課題となっている。','가정 환경에 따른 학력 격차가 과제가 되고 있다.'),
('n1-3114','2026-12-29','活力','かつりょく','활력; 힘차게 활동하게 하는 에너지','元気に活動するための力や勢い。','若い世代の参加が地域に新たな活力をもたらした。','젊은 세대의 참여가 지역에 새로운 활력을 가져왔다.'),
('n1-3115','2026-12-29','芸能','げいのう','예능; 연극·음악·무용 등 사람 앞에서 보이는 기예','演劇、音楽、舞踊など、人前で演じる技芸。','伝統芸能を次の世代へ継承する活動が続いている。','전통 예능을 다음 세대에 계승하는 활동이 이어지고 있다.'),
('n1-3116','2026-12-29','災難','さいなん','재난; 뜻밖에 닥친 불행이나 재해','思いがけず身に降りかかる不幸や災い。','旅先で財布を失う災難に見舞われた。','여행지에서 지갑을 잃는 재난을 당했다.'),
('n1-3117','2026-12-29','実力','じつりょく','실력; 실제로 갖추고 있는 능력','実際に備えている能力や力量。','本番で実力を十分に発揮できなかった。','본 시험에서 실력을 충분히 발휘하지 못했다.'),
('n1-3118','2026-12-29','重力','じゅうりょく','중력; 물체를 지구 중심 쪽으로 끌어당기는 힘','物体を地球の中心方向へ引き寄せる力。','宇宙空間では重力の影響が地上とは異なる。','우주 공간에서는 중력의 영향이 지상과 다르다.'),
('n1-3119','2026-12-29','衣食住','いしょくじゅう','의식주; 옷·음식·주거라는 생활의 기본 요소','衣服、食事、住居という生活の基本的な要素。','被災者の衣食住を確保する支援が急がれる。','이재민의 의식주를 확보하는 지원이 시급하다.'),
('n1-3120','2026-12-29','曖昧','あいまい','애매; 분명하지 않아 여러 해석이 가능함','内容や態度がはっきりせず、複数の解釈ができるさま。','責任の範囲が曖昧なため、対応が遅れた。','책임 범위가 애매해서 대응이 늦어졌다.');
INSERT INTO _n1_b7_words_0122(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3121','2026-12-30','務める','つとめる','맡다; 역할이나 직책을 담당하다','役割や職務を引き受けて果たす。','委員会の議長を務めるには、公正な進行が求められる。','위원회 의장을 맡으려면 공정한 진행이 요구된다.'),
('n1-3122','2026-12-30','緩い','ゆるい','느슨하다; 엄격하지 않다; 완만하다','締まりや制限が弱い。また、傾斜や速度が急でない。','規制が緩い地域では同じ問題が起こりやすい。','규제가 느슨한 지역에서는 같은 문제가 생기기 쉽다.'),
('n1-3123','2026-12-30','論ずる','ろんずる','논하다; 근거를 들어 의견을 전개하다','筋道を立てて意見や考えを述べる。','結果だけでなく、その原因についても論ずる必要がある。','결과뿐 아니라 그 원인에 대해서도 논할 필요가 있다.'),
('n1-3124','2026-12-30','安易','あんい','안이; 깊이 생각하지 않고 쉽게 처리하려 함','十分に考えず、簡単に済ませようとするさま。','安易な判断で方針を変更すべきではない。','안이한 판단으로 방침을 변경해서는 안 된다.'),
('n1-3125','2026-12-30','案外','あんがい','의외로; 예상과 달리','予想していたことと違うさま。','難しそうに見えたが、実際の作業は案外簡単だった。','어려워 보였지만 실제 작업은 의외로 간단했다.'),
('n1-3126','2026-12-30','幾分','いくぶん','다소; 어느 정도','数量や程度が少しであるさま。','説明を聞いて不安が幾分和らいだ。','설명을 듣고 불안이 다소 누그러졌다.'),
('n1-3127','2026-12-30','以後','いご','이후; 어떤 시점을 포함해 그 뒤','ある時点から後。','この事故以後、安全基準が大幅に見直された。','이 사고 이후 안전 기준이 대폭 재검토되었다.'),
('n1-3128','2026-12-30','以降','いこう','이후; 기준이 되는 시점부터 뒤','基準となる時点を含み、それより後。','来月以降の予定はまだ決まっていない。','다음 달 이후의 일정은 아직 정해지지 않았다.'),
('n1-3129','2026-12-30','一応','いちおう','일단; 완전하지는 않지만 필요한 정도로','十分とは言えないが、ひとまず必要な程度には。','提出前に一応すべての項目を確認した。','제출 전에 일단 모든 항목을 확인했다.'),
('n1-3130','2026-12-30','一段','いちだん','한층; 이전보다 더욱','以前の状態と比べて、さらに程度が増すさま。','制度の改正によって利便性が一段と高まった。','제도 개정으로 편의성이 한층 높아졌다.'),
('n1-3131','2026-12-30','一流','いちりゅう','일류; 수준이 가장 높은 부류','技術や品質などが最も優れた部類。','一流の専門家ほど基礎を大切にする。','일류 전문가일수록 기초를 중요하게 여긴다.'),
('n1-3132','2026-12-30','一斉','いっせい','일제히; 많은 사람이 동시에 행동하는 모양','多くの人や物が同時に同じ動きをするさま。','警報が鳴ると、住民は一斉に避難を始めた。','경보가 울리자 주민들은 일제히 대피를 시작했다.'),
('n1-3133','2026-12-30','一旦','いったん','일단; 우선 잠시; 한번 어떤 상태가 되면','ひとまず一度。また、ある状態になった場合。','議論が混乱したため、会議を一旦中断した。','논의가 혼란스러워 회의를 일단 중단했다.'),
('n1-3134','2026-12-30','一定','いってい','일정; 정해져 있어 변하지 않음','決まっていて変わらないこと。また、ある程度。','応募には一定の実務経験が必要だ。','지원하려면 일정 수준의 실무 경험이 필요하다.'),
('n1-3135','2026-12-30','売上','うりあげ','매출; 상품이나 서비스를 판매해 얻은 금액','商品やサービスを売って得た金額。','新商品の発売後、月間の売上が大きく伸びた。','신제품 출시 후 월간 매출이 크게 늘었다.'),
('n1-3136','2026-12-30','運河','うんが','운하; 선박 운항 등을 위해 만든 수로','船の航行などのために人工的に造った水路。','運河の建設によって物流経路が短縮された。','운하 건설로 물류 경로가 단축되었다.'),
('n1-3137','2026-12-30','液体','えきたい','액체; 일정한 부피는 있지만 고정된 모양이 없는 물질','一定の体積を持つが、決まった形を持たない物質。','この液体は低温になると固体に変化する。','이 액체는 저온이 되면 고체로 변한다.'),
('n1-3138','2026-12-30','演劇','えんげき','연극; 배우가 무대에서 이야기를 표현하는 예술','俳優が舞台上で物語を表現する芸術。','地域の歴史を題材にした演劇が上演された。','지역 역사를 소재로 한 연극이 공연되었다.'),
('n1-3139','2026-12-30','延長','えんちょう','연장; 길이나 기간을 늘림','長さや期間をさらに長くすること。','工事の遅れにより契約期間を延長した。','공사 지연으로 계약 기간을 연장했다.'),
('n1-3140','2026-12-30','応接','おうせつ','응접; 찾아온 사람을 맞아 상대함','訪ねてきた人を迎えて相手をすること。','来客を応接するための部屋を改装した。','방문객을 응접하기 위한 방을 개조했다.'),
('n1-3141','2026-12-31','応対','おうたい','응대; 상대의 말이나 요구에 맞추어 대응함','相手の話や要求に応じて受け答えすること。','窓口では利用者に丁寧に応対する必要がある。','창구에서는 이용자에게 정중히 응대할 필요가 있다.'),
('n1-3142','2026-12-31','往復','おうふく','왕복; 갔다가 돌아옴','目的地まで行き、再び出発地へ戻ること。','自宅と職場を毎日二時間かけて往復している。','집과 직장을 매일 두 시간 걸려 왕복하고 있다.'),
('n1-3143','2026-12-31','欧米','おうべい','구미; 유럽과 미국','ヨーロッパとアメリカ。','この制度は欧米の事例を参考に設計された。','이 제도는 유럽과 미국의 사례를 참고해 설계되었다.'),
('n1-3144','2026-12-31','各々','おのおの','각각; 저마다','一人一人、または一つ一つ。それぞれ。','参加者が各々の立場から意見を述べた。','참가자들이 각각의 입장에서 의견을 말했다.'),
('n1-3145','2026-12-31','恩恵','おんけい','은혜; 혜택; 도움을 받아 누리는 이익','恵みや助けによって受ける利益。','多くの地域が技術革新の恩恵を受けている。','많은 지역이 기술 혁신의 혜택을 받고 있다.'),
('n1-3146','2026-12-31','解散','かいさん','해산; 모임이나 조직을 없애거나 흩어짐','集まっていた人が別れること。また、組織をなくすこと。','目的を達成したため、調査委員会は解散した。','목적을 달성하여 조사위원회는 해산했다.'),
('n1-3147','2026-12-31','開通','かいつう','개통; 도로나 철도·통신 등이 이용 가능해짐','道路、鉄道、通信などが通じて利用可能になること。','新しい鉄道路線が来年開通する予定だ。','새 철도 노선이 내년에 개통될 예정이다.'),
('n1-3148','2026-12-31','回転','かいてん','회전; 축이나 중심을 기준으로 빙돎','軸や中心の周りをぐるりと回ること。','装置の回転速度を一定に保つ。','장치의 회전 속도를 일정하게 유지한다.'),
('n1-3149','2026-12-31','解答','かいとう','해답; 문제를 풀어 낸 답','問題を解いて示した答え。','試験終了後に模範解答が公表された。','시험 종료 후 모범 해답이 공개되었다.'),
('n1-3150','2026-12-31','回答','かいとう','회답; 질문이나 요구에 대한 답변','質問や要求に対して答えること、またはその答え。','問い合わせには三営業日以内に回答する。','문의에는 영업일 기준 3일 이내에 답변한다.'),
('n1-3151','2026-12-31','外部','がいぶ','외부; 조직이나 물체의 바깥쪽','組織や物体の外側、または関係者以外。','個人情報を外部へ持ち出すことは禁止されている。','개인정보를 외부로 반출하는 것은 금지되어 있다.'),
('n1-3152','2026-12-31','開放','かいほう','개방; 문이나 시설 등을 열어 자유롭게 이용하게 함','閉じていた場所や施設を開き、自由に利用できるようにすること。','休日には校庭を地域住民に開放している。','휴일에는 운동장을 지역 주민에게 개방하고 있다.'),
('n1-3153','2026-12-31','海洋','かいよう','해양; 넓고 큰 바다','広大な海。また、海に関する領域。','海洋汚染を防ぐため国際的な協力が必要だ。','해양 오염을 막기 위해 국제적인 협력이 필요하다.'),
('n1-3154','2026-12-31','架空','かくう','가공; 실제로 존재하지 않고 상상으로 만든 것','実際には存在せず、想像によって作られたこと。','物語は架空の都市を舞台にしている。','이야기는 가공의 도시를 무대로 한다.'),
('n1-3155','2026-12-31','各自','かくじ','각자; 각각의 사람','一人一人。それぞれの人。','資料は各自で事前に確認してください。','자료는 각자 사전에 확인해 주세요.'),
('n1-3156','2026-12-31','各地','かくち','각지; 여러 지역','それぞれの地域。あちこちの土地。','大雨による被害が全国各地で報告された。','폭우로 인한 피해가 전국 각지에서 보고되었다.'),
('n1-3157','2026-12-31','格別','かくべつ','각별; 보통과 달리 특별함','普通とは違って特別であるさま。','長い努力の末に得た成果は格別だった。','오랜 노력 끝에 얻은 성과는 각별했다.'),
('n1-3158','2026-12-31','下降','かこう','하강; 아래로 내려감; 수치가 떨어짐','位置や数値が下へ向かって下がること。','気温は夕方から急速に下降した。','기온은 저녁부터 급속히 하강했다.'),
('n1-3159','2026-12-31','活躍','かつやく','활약; 능력을 발휘하여 두드러지게 활동함','能力を発揮して、目立った活動をすること。','若手研究者が国際的な舞台で活躍している。','젊은 연구자가 국제 무대에서 활약하고 있다.'),
('n1-3160','2026-12-31','鑑賞','かんしょう','감상; 예술 작품의 가치를 느끼며 즐김','芸術作品を味わい、その価値や美しさを楽しむこと。','作品を鑑賞した後、表現技法について話し合った。','작품을 감상한 뒤 표현 기법에 관해 이야기했다.');
INSERT INTO _n1_b7_words_0122(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3161','2027-01-01','工夫','くふう','궁리; 좋은 방법을 찾아 여러모로 생각함','よりよい方法を見つけるために考えを巡らせること。','限られた予算でも成果を出せるよう工夫した。','한정된 예산으로도 성과를 낼 수 있도록 궁리했다.'),
('n1-3162','2027-01-01','敬語','けいご','경어; 상대를 높이거나 공손함을 나타내는 말','相手や話題の人物への敬意を表す言葉遣い。','場面に応じて適切な敬語を使い分ける必要がある。','상황에 따라 적절한 경어를 구분해 사용할 필요가 있다.'),
('n1-3163','2027-01-01','警備','けいび','경비; 사고나 범죄를 막기 위해 지킴','事故や犯罪を防ぐために見張り、守ること。','会場周辺の警備を強化して混乱に備えた。','행사장 주변 경비를 강화해 혼란에 대비했다.'),
('n1-3164','2027-01-01','傑作','けっさく','걸작; 매우 뛰어난 작품','特に優れた出来栄えの作品。','この小説は作家の代表的な傑作として評価されている。','이 소설은 작가의 대표적인 걸작으로 평가받고 있다.'),
('n1-3165','2027-01-01','下品','げひん','상스럽다; 품위가 없음','言動や趣味に品位がなく、卑しいさま。','人を傷つける下品な冗談は慎むべきだ。','남에게 상처를 주는 상스러운 농담은 삼가야 한다.'),
('n1-3166','2027-01-01','研修','けんしゅう','연수; 업무에 필요한 지식과 기술을 배우는 과정','仕事に必要な知識や技能を身につけるための学習。','新入社員は一か月間の研修を受ける。','신입 사원은 한 달간 연수를 받는다.'),
('n1-3167','2027-01-01','限度','げんど','한도; 허용하거나 가능한 범위의 끝','許容できる範囲や可能な範囲の上限。','個人の努力だけで対応するには限度がある。','개인의 노력만으로 대응하는 데에는 한도가 있다.'),
('n1-3168','2027-01-01','原料','げんりょう','원료; 제품을 만드는 데 바탕이 되는 재료','製品を作るもとになる材料。','原料価格の上昇が製品価格に反映された。','원료 가격 상승이 제품 가격에 반영되었다.'),
('n1-3169','2027-01-01','強引','ごういん','강압적; 무리하게 일을 밀어붙이는 모양','相手の事情を考えず、無理に物事を進めるさま。','十分な合意のないまま強引に計画を進めた。','충분한 합의 없이 강압적으로 계획을 추진했다.'),
('n1-3170','2027-01-01','高級','こうきゅう','고급; 품질이나 등급이 높음','品質や等級が高く、価値があること。','高級な素材を使えば必ず良い製品になるとは限らない。','고급 소재를 쓴다고 반드시 좋은 제품이 되는 것은 아니다.'),
('n1-3171','2027-01-01','工芸','こうげい','공예; 실용성과 아름다움을 갖춘 물건을 만드는 기술','実用性と美しさを備えた品物を作る技術。','地域の伝統工芸を海外に紹介する展示会が開かれた。','지역의 전통 공예를 해외에 소개하는 전시회가 열렸다.'),
('n1-3172','2027-01-01','交差','こうさ','교차; 서로 엇갈려 지나거나 만남','二つ以上の線や動きが互いに交わること。','複数の要因が交差して問題を複雑にしている。','여러 요인이 교차해 문제를 복잡하게 만들고 있다.'),
('n1-3173','2027-01-01','講師','こうし','강사; 강의나 지도를 담당하는 사람','講義や指導を担当する人。','外部から専門分野の講師を招いて研修を行った。','외부에서 전문 분야 강사를 초청해 연수를 진행했다.'),
('n1-3174','2027-01-01','公衆','こうしゅう','공중; 사회를 이루는 일반 대중','社会を構成する不特定多数の人々。','公衆の安全を守るため施設を一時閉鎖した。','일반 대중의 안전을 지키기 위해 시설을 일시 폐쇄했다.'),
('n1-3175','2027-01-01','高層','こうそう','고층; 건물의 높은 층이나 높이 솟은 구조','建物の高い階層、または高くそびえること。','高層建築では地震への十分な対策が必要だ。','고층 건축물에서는 지진에 대한 충분한 대책이 필요하다.'),
('n1-3176','2027-01-01','交替','こうたい','교대; 역할을 서로 바꾸어 맡음','役割や担当を入れ替わって受け持つこと。','作業員は二時間ごとに交替して監視を続けた。','작업원들은 두 시간마다 교대하며 감시를 계속했다.'),
('n1-3177','2027-01-01','高度','こうど','고도; 높은 수준; 지표면에서의 높이','程度や水準が高いこと。また、地表からの高さ。','この業務には高度な専門知識が求められる。','이 업무에는 고도의 전문 지식이 요구된다.'),
('n1-3178','2027-01-01','合同','ごうどう','합동; 둘 이상의 조직이 함께함','二つ以上の組織や集団が一緒に行うこと。','三つの自治体が合同で防災訓練を実施した。','세 지자체가 합동으로 방재 훈련을 실시했다.'),
('n1-3179','2027-01-01','交流','こうりゅう','교류; 서로 오가며 관계를 맺고 영향을 주고받음','人や組織が互いに行き来し、関係や情報を交換すること。','地域間の交流を促すため共同事業を始めた。','지역 간 교류를 촉진하기 위해 공동 사업을 시작했다.'),
('n1-3180','2027-01-01','合流','ごうりゅう','합류; 서로 다른 흐름이나 집단이 하나로 합쳐짐','別々の流れや集団が一つになること。','現地で別の調査班と合流する予定だ。','현지에서 다른 조사반과 합류할 예정이다.'),
('n1-3181','2027-01-02','国立','こくりつ','국립; 국가가 설립하고 운영함','国が設立し、運営すること。','資料は国立の研究機関が公開している。','자료는 국립 연구기관이 공개하고 있다.'),
('n1-3182','2027-01-02','娯楽','ごらく','오락; 즐거움을 얻기 위한 활동','仕事や勉強を離れて楽しむための活動。','娯楽の多様化によって余暇の過ごし方も変わった。','오락의 다양화로 여가를 보내는 방식도 달라졌다.'),
('n1-3183','2027-01-02','混合','こんごう','혼합; 서로 다른 것을 섞음','性質の異なる複数のものを混ぜ合わせること。','二種類の原料を一定の割合で混合する。','두 종류의 원료를 일정 비율로 혼합한다.'),
('n1-3184','2027-01-02','採点','さいてん','채점; 답안을 평가하여 점수를 매김','答案を評価し、点数をつけること。','公平な基準に基づいて答案を採点した。','공정한 기준에 따라 답안을 채점했다.'),
('n1-3185','2027-01-02','撮影','さつえい','촬영; 사진이나 영상을 찍음','写真や映像をカメラで記録すること。','施設内での撮影には事前の許可が必要だ。','시설 내 촬영에는 사전 허가가 필요하다.'),
('n1-3186','2027-01-02','雑音','ざつおん','잡음; 필요하지 않은 소리나 신호','聞き取りや通信を妨げる不要な音や信号。','雑音が多く、通話の内容を聞き取れなかった。','잡음이 많아 통화 내용을 알아듣지 못했다.'),
('n1-3187','2027-01-02','早速','さっそく','즉시; 지체하지 않고 바로','時間を置かず、すぐに行動するさま。','提案が承認されたので、早速準備に取りかかった。','제안이 승인되어 즉시 준비에 착수했다.'),
('n1-3188','2027-01-02','産地','さんち','산지; 어떤 생산물이 주로 생산되는 지역','特定の生産物を多く産出する地域。','産地によって品質や風味に違いがある。','산지에 따라 품질과 풍미에 차이가 있다.'),
('n1-3189','2027-01-02','敷地','しきち','부지; 건물이나 시설이 들어선 토지','建物や施設を建てるために区切られた土地。','工場の敷地内では安全規則を守らなければならない。','공장 부지 안에서는 안전 규칙을 지켜야 한다.'),
('n1-3190','2027-01-02','至急','しきゅう','지급; 매우 급함; 최대한 빨리','非常に急ぐこと。できるだけ早く。','不具合の原因を至急調査してください。','오류 원인을 최대한 빨리 조사해 주세요.'),
('n1-3191','2027-01-02','持参','じさん','지참; 직접 가지고 감','必要な物を自分で持って行くこと。','本人確認書類を当日持参してください。','본인 확인 서류를 당일 지참해 주세요.'),
('n1-3192','2027-01-02','始終','しじゅう','시종; 처음부터 끝까지; 늘','初めから終わりまで。また、絶えず。','会議中、彼は始終落ち着いた態度を保っていた。','회의 중 그는 시종 침착한 태도를 유지했다.'),
('n1-3193','2027-01-02','姿勢','しせい','자세; 몸가짐; 어떤 일에 임하는 태도','体の構え。また、物事に取り組む態度。','問題に誠実に向き合う姿勢が評価された。','문제에 성실히 임하는 자세가 평가받았다.'),
('n1-3194','2027-01-02','子孫','しそん','자손; 후대에 이어지는 자녀와 그 후손','子や孫など、後の世代に続く血縁者。','豊かな自然を子孫に残す責任がある。','풍요로운 자연을 자손에게 남길 책임이 있다.'),
('n1-3195','2027-01-02','実習','じっしゅう','실습; 실제 작업을 통해 기술을 익힘','実際の作業を行いながら知識や技能を学ぶこと。','講義の後に機器を使った実習を行った。','강의 후 기기를 사용한 실습을 진행했다.'),
('n1-3196','2027-01-02','実物','じつぶつ','실물; 사진이나 모형이 아닌 실제 물건','写真や模型ではない、実際の物。','実物を確認すると、写真とは色合いが異なっていた。','실물을 확인하니 사진과 색감이 달랐다.'),
('n1-3197','2027-01-02','実例','じつれい','실례; 실제로 있었던 구체적인 사례','実際に起きた具体的な例。','制度の効果を実例を挙げて説明した。','제도의 효과를 실제 사례를 들어 설명했다.'),
('n1-3198','2027-01-02','弱点','じゃくてん','약점; 부족하거나 취약한 부분','能力や仕組みの中で弱く、不利になる部分。','システムの弱点を把握し、事前に対策を講じた。','시스템의 약점을 파악해 사전에 대책을 마련했다.'),
('n1-3199','2027-01-02','集会','しゅうかい','집회; 공통 목적을 가진 사람들이 모이는 일','共通の目的を持つ人々が集まること、またはその会。','住民集会で再開発計画について意見を交換した。','주민 집회에서 재개발 계획에 관한 의견을 나눴다.'),
('n1-3200','2027-01-02','周辺','しゅうへん','주변; 어떤 장소나 대상의 가까운 범위','ある場所や物のまわりの地域。','駅周辺の交通量を調査して対策を検討した。','역 주변의 교통량을 조사해 대책을 검토했다.');
INSERT INTO _n1_b7_words_0122(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3201','2027-01-03','集合','しゅうごう','집합; 한곳에 모임; 수학에서 일정 조건을 만족하는 대상의 모임','一か所に集まること。また、数学で一定条件を満たす要素の集まり。','参加者は開始時刻の十分前に集合してください。','참가자는 시작 시각 10분 전에 집합해 주세요.'),
('n1-3202','2027-01-03','重体','じゅうたい','중태; 병이나 부상이 매우 심각한 상태','病気や負傷の程度が非常に重く、危険な状態。','事故で負傷した一人が重体だと発表された。','사고로 다친 한 명이 중태라고 발표되었다.'),
('n1-3203','2027-01-03','終了','しゅうりょう','종료; 일이나 행사가 끝남','物事や予定された行事が終わること。','受付は予定時刻より早く終了した。','접수는 예정 시각보다 일찍 종료되었다.'),
('n1-3204','2027-01-03','重量','じゅうりょう','중량; 물체의 무게','物体の重さ。','荷物の重量が制限を超えていないか確認した。','짐의 중량이 제한을 넘지 않았는지 확인했다.'),
('n1-3205','2027-01-03','熟語','じゅくご','숙어; 두 글자 이상의 한자 결합이나 관용적인 어구','複数の漢字から成る語、または慣用的に使われる語句。','漢字単体だけでなく熟語の読み方も覚える。','한자 하나뿐 아니라 숙어의 읽는 법도 외운다.'),
('n1-3206','2027-01-03','出勤','しゅっきん','출근; 근무처에 나감','勤務先へ仕事をしに出かけること。','大雪のため出勤時刻を遅らせることになった。','폭설 때문에 출근 시각을 늦추기로 했다.'),
('n1-3207','2027-01-03','出張','しゅっちょう','출장; 업무 때문에 다른 지역으로 감','仕事のために一時的に別の地域へ行くこと。','来週は取引先との打ち合わせで大阪へ出張する。','다음 주에는 거래처와 회의하기 위해 오사카로 출장 간다.'),
('n1-3208','2027-01-03','寿命','じゅみょう','수명; 생물이 살아 있는 기간; 기계가 사용 가능한 기간','生物が生きる期間。また、機械などが使用できる期間。','適切な保守によって設備の寿命を延ばせる。','적절한 유지보수로 설비의 수명을 늘릴 수 있다.'),
('n1-3209','2027-01-03','主役','しゅやく','주역; 작품의 중심 역할; 일의 중심 인물','作品の中心となる役。また、物事の中心となる人物。','地域の再生では住民自身が主役になるべきだ。','지역 재생에서는 주민 스스로가 주역이 되어야 한다.'),
('n1-3210','2027-01-03','純情','じゅんじょう','순정; 순수하고 꾸밈없는 마음','素直で、邪念や打算のない心。','純情な若者の成長を描いた物語だ。','순정적인 젊은이의 성장을 그린 이야기다.'),
('n1-3211','2027-01-03','商業','しょうぎょう','상업; 상품이나 서비스를 거래하여 이익을 얻는 활동','商品やサービスを売買して利益を得る事業。','駅前では大規模な商業施設の建設が進んでいる。','역 앞에서는 대규모 상업 시설 건설이 진행되고 있다.'),
('n1-3212','2027-01-03','商社','しょうしゃ','상사; 국내외 상품 거래를 중개하는 회사','国内外の商品取引を仲介する会社。','商社は海外企業との交渉を担当した。','상사는 해외 기업과의 협상을 담당했다.'),
('n1-3213','2027-01-03','消毒','しょうどく','소독; 병원성 미생물을 없애거나 약화함','病原性のある微生物を除去したり弱めたりすること。','使用後の器具は必ず消毒してください。','사용한 기구는 반드시 소독해 주세요.'),
('n1-3214','2027-01-03','勝敗','しょうはい','승패; 이김과 짐','勝つことと負けること。','一度の勝敗だけで選手の実力は判断できない。','한 번의 승패만으로 선수의 실력을 판단할 수 없다.'),
('n1-3215','2027-01-03','蒸発','じょうはつ','증발; 액체가 기체로 변함; 사람이 자취를 감춤','液体が気体に変わること。また、人が突然姿を消すこと。','気温が上がると水分の蒸発が速くなる。','기온이 오르면 수분의 증발이 빨라진다.'),
('n1-3216','2027-01-03','正味','しょうみ','순수분; 겉포장 등을 제외한 실제 양이나 내용','余分なものを除いた実質的な量や内容。','休憩を除くと正味の作業時間は六時間だった。','휴식을 빼면 실제 작업 시간은 6시간이었다.'),
('n1-3217','2027-01-03','正面','しょうめん','정면; 바로 앞쪽; 피하지 않고 직접 대함','物の真正面。また、物事に逃げず直接向き合うこと。','難しい課題に正面から向き合う必要がある。','어려운 과제에 정면으로 맞설 필요가 있다.'),
('n1-3218','2027-01-03','職人','しょくにん','장인; 숙련된 기술로 물건을 만드는 사람','熟練した技術によって物を作る人。','職人の技術を若い世代へ継承する。','장인의 기술을 젊은 세대에 계승한다.'),
('n1-3219','2027-01-03','書籍','しょせき','서적; 책과 출판물','本として出版されたもの。書物。','専門分野の書籍を図書館から借りた。','전문 분야 서적을 도서관에서 빌렸다.'),
('n1-3220','2027-01-03','私立','しりつ','사립; 민간이 설립하고 운영함','民間の個人や法人が設立し、運営すること。','公立と私立では費用や教育方針が異なる。','공립과 사립은 비용과 교육 방침이 다르다.'),
('n1-3221','2027-01-04','感激','かんげき','감격; 마음이 크게 움직여 깊이 감동함','心を強く動かされ、深く感動すること。','長年の努力を認められ、本人は感激していた。','오랜 노력을 인정받아 본인은 감격해 있었다.'),
('n1-3222','2027-01-04','乾燥','かんそう','건조; 수분이 없어 마름','水分がなくなり、乾くこと。','空気が乾燥する季節は火災に注意が必要だ。','공기가 건조한 계절에는 화재에 주의해야 한다.'),
('n1-3223','2027-01-04','感想','かんそう','감상; 보고 듣거나 경험한 뒤 느낀 생각','見聞きしたり経験したりした後に抱く思い。','講演を聞いた感想を簡潔にまとめた。','강연을 들은 감상을 간결하게 정리했다.'),
('n1-3224','2027-01-04','飢饉','ききん','기근; 식량이 심각하게 부족해 굶주리는 상태','食料が著しく不足し、多くの人が飢える状態。','長期の干ばつが深刻な飢饉を引き起こした。','장기간의 가뭄이 심각한 기근을 일으켰다.'),
('n1-3225','2027-01-04','器具','きぐ','기구; 특정 작업에 사용하는 도구','特定の作業や目的に使用する道具。','実験に使う器具を事前に点検した。','실험에 사용할 기구를 사전에 점검했다.'),
('n1-3226','2027-01-04','記号','きごう','기호; 일정한 의미를 나타내는 표시','一定の意味や内容を表すためのしるし。','地図上の記号が何を示すか確認した。','지도 위의 기호가 무엇을 나타내는지 확인했다.'),
('n1-3227','2027-01-04','儀式','ぎしき','의식; 정해진 절차에 따라 치르는 행사','決められた作法や手順に従って行う行事。','伝統的な儀式が地域の人々によって受け継がれている。','전통 의식이 지역 주민들에게 계승되고 있다.'),
('n1-3228','2027-01-04','基地','きち','기지; 군사·관측·활동 등의 거점','軍事、観測、活動などの拠点となる場所。','南極の観測基地で気象データを収集する。','남극 관측 기지에서 기상 데이터를 수집한다.'),
('n1-3229','2027-01-04','休業','きゅうぎょう','휴업; 영업이나 업무를 일시적으로 쉼','営業や業務を一時的に休むこと。','設備点検のため工場は一週間休業する。','설비 점검 때문에 공장은 일주일간 휴업한다.'),
('n1-3230','2027-01-04','給与','きゅうよ','급여; 근로의 대가로 지급되는 돈','労働の対価として支払われる金銭。','経験や能力を給与に適切に反映させる。','경험과 능력을 급여에 적절히 반영한다.'),
('n1-3231','2027-01-04','休養','きゅうよう','휴양; 몸과 마음을 쉬게 해 회복함','仕事などを休み、心身を回復させること。','医師から十分な休養を取るよう勧められた。','의사에게 충분한 휴양을 취하라는 권고를 받았다.'),
('n1-3232','2027-01-04','行事','ぎょうじ','행사; 일정한 때와 절차에 따라 치르는 일','一定の時期や手順に従って行われる催し。','地域の伝統行事に多くの住民が参加した。','지역 전통 행사에 많은 주민이 참가했다.'),
('n1-3233','2027-01-04','恐縮','きょうしゅく','송구; 고마움이나 미안함 때문에 몸 둘 바를 모름','相手の厚意や迷惑をかけることに対して、申し訳なく思うこと。','お忙しいところ恐縮ですが、ご確認をお願いします。','바쁘신 중에 송구하지만 확인 부탁드립니다.'),
('n1-3234','2027-01-04','漁業','ぎょぎょう','어업; 물고기나 해산물을 잡거나 기르는 산업','魚介類を捕獲したり養殖したりする産業。','海水温の変化が地域の漁業に影響を与えている。','해수 온도 변화가 지역 어업에 영향을 주고 있다.'),
('n1-3235','2027-01-04','空想','くうそう','공상; 현실과 떨어진 일을 자유롭게 상상함','現実にはないことを自由に思い描くこと。','子どもの頃は未来の都市を空想していた。','어릴 때는 미래 도시를 공상하곤 했다.'),
('n1-3236','2027-01-04','苦情','くじょう','불만; 피해나 불편에 대해 제기하는 항의','被害や不満について相手に訴えること、またはその内容。','騒音に関する苦情が住民から寄せられた。','소음에 관한 불만이 주민들로부터 접수되었다.'),
('n1-3237','2027-01-04','苦心','くしん','고심; 해결책을 찾기 위해 몹시 애씀','よい方法を得るために心を悩ませ、努力すること。','担当者は限られた予算で質を保つことに苦心した。','담당자는 한정된 예산으로 품질을 유지하는 데 고심했다.'),
('n1-3238','2027-01-04','青少年','せいしょうねん','청소년; 어린이와 젊은 세대를 아우르는 말','少年と青年を合わせた、若い世代。','青少年の健全な育成を支援する事業を始めた。','청소년의 건전한 육성을 지원하는 사업을 시작했다.'),
('n1-3239','2027-01-04','必需品','ひつじゅひん','필수품; 생활이나 활동에 반드시 필요한 물품','生活や活動に欠かすことのできない品物。','被災地へ水や毛布などの必需品を届けた。','재해 지역에 물과 담요 같은 필수품을 전달했다.'),
('n1-3240','2027-01-04','無沙汰','ぶさた','무소식; 오랫동안 연락하거나 방문하지 못함','長い間、連絡や訪問をしないこと。','長らく無沙汰していた恩師に手紙を書いた。','오랫동안 소식이 뜸했던 은사에게 편지를 썼다.');
INSERT INTO _n1_b7_words_0122(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3241','2027-01-05','酸性','さんせい','산성; 산의 성질을 띠는 상태','酸としての性質を示す状態。','酸性の強い土壌では育ちにくい植物もある。','산성이 강한 토양에서는 자라기 어려운 식물도 있다.'),
('n1-3242','2027-01-05','中性','ちゅうせい','중성; 산성도 알칼리성도 아닌 상태; 어느 쪽에도 치우치지 않음','酸性でもアルカリ性でもない状態。また、どちらにも偏らないこと。','この洗剤は中性なので素材を傷めにくい。','이 세제는 중성이어서 소재를 손상시키기 어렵다.'),
('n1-3243','2027-01-05','性別','せいべつ','성별; 성에 따른 구분','性による区別。','性別にかかわらず能力を公平に評価する。','성별과 관계없이 능력을 공정하게 평가한다.'),
('n1-3244','2027-01-05','応援','おうえん','응원; 힘을 북돋우거나 도움을 줌','励ましたり、力を貸したりして助けること。','地域全体で若い起業家を応援する取り組みが始まった。','지역 전체가 젊은 창업가를 응원하는 사업이 시작되었다.'),
('n1-3245','2027-01-05','加速度','かそくど','가속도; 단위 시간당 속도의 변화량','単位時間当たりの速度の変化量。','技術革新が加速度を増して進んでいる。','기술 혁신이 가속도를 더하며 진행되고 있다.'),
('n1-3246','2027-01-05','水平線','すいへいせん','수평선; 바다와 하늘이 맞닿아 보이는 선','海面と空が接しているように見える境界線。','水平線の向こうから太陽が昇った。','수평선 너머에서 해가 떠올랐다.'),
('n1-3247','2027-01-05','大学院','だいがくいん','대학원; 대학 졸업 후 전문 연구를 하는 교육기관','大学卒業後に専門的な研究や教育を行う機関。','大学院で環境政策について研究している。','대학원에서 환경 정책을 연구하고 있다.'),
('n1-3248','2027-01-05','地下水','ちかすい','지하수; 땅속에 스며들어 존재하는 물','地中にしみ込み、地下に存在する水。','工場周辺の地下水に汚染がないか調査した。','공장 주변 지하수에 오염이 없는지 조사했다.'),
('n1-3249','2027-01-05','農産物','のうさんぶつ','농산물; 농업을 통해 생산한 물품','農業によって生産される作物や品物。','地元の農産物を使った商品を開発した。','지역 농산물을 사용한 상품을 개발했다.'),
('n1-3250','2027-01-05','育児','いくじ','육아; 어린아이를 돌보고 기름','幼い子どもを世話し、育てること。','仕事と育児を両立できる制度が求められている。','일과 육아를 병행할 수 있는 제도가 요구되고 있다.'),
('n1-3251','2027-01-05','緯度','いど','위도; 적도를 기준으로 한 남북 방향의 위치','赤道を基準にした南北方向の位置。','同じ緯度でも海流によって気候が異なる。','같은 위도라도 해류에 따라 기후가 다르다.'),
('n1-3252','2027-01-05','園芸','えんげい','원예; 채소·과일·화초 등을 재배하는 일','野菜、果樹、草花などを栽培すること。','園芸を通じて地域住民の交流を深める。','원예를 통해 지역 주민의 교류를 깊게 한다.'),
('n1-3253','2027-01-05','温帯','おんたい','온대; 열대와 한대 사이의 기후대','熱帯と寒帯の間にある気候帯。','日本の大部分は温帯に属している。','일본의 대부분은 온대에 속한다.'),
('n1-3254','2027-01-05','開会','かいかい','개회; 회의나 행사를 시작함','会議や催しを始めること。','定刻になり、議長が開会を宣言した。','정각이 되어 의장이 개회를 선언했다.'),
('n1-3255','2027-01-05','会館','かいかん','회관; 집회나 행사에 사용하는 건물','集会や催しなどに使用する建物。','説明会は市民会館で開催される。','설명회는 시민회관에서 열린다.'),
('n1-3256','2027-01-05','回数','かいすう','횟수; 일이 반복된 수','物事が繰り返された数。','利用回数に応じて料金が割引される。','이용 횟수에 따라 요금이 할인된다.'),
('n1-3257','2027-01-05','家屋','かおく','가옥; 사람이 거주하거나 사용하는 건물','人が住んだり利用したりする建物。','台風によって多くの家屋が被害を受けた。','태풍으로 많은 가옥이 피해를 입었다.'),
('n1-3258','2027-01-05','角度','かくど','각도; 두 선이나 면이 이루는 벌어진 정도; 관점','二つの線や面が作る開きの大きさ。また、物を見る観点。','異なる角度から問題を検討する必要がある。','다른 각도에서 문제를 검토할 필요가 있다.'),
('n1-3259','2027-01-05','学部','がくぶ','학부; 대학에서 전공 분야별로 나눈 조직','大学で専門分野ごとに分けられた教育組織。','希望する学部の教育内容を事前に調べた。','희망하는 학부의 교육 내용을 사전에 조사했다.'),
('n1-3260','2027-01-05','火山','かざん','화산; 지하의 마그마 등이 분출하는 산','地下のマグマなどが地表へ噴出する山。','火山の活動を継続的に観測している。','화산 활동을 지속적으로 관측하고 있다.'),
('n1-3261','2027-01-06','加速','かそく','가속; 속도를 더 빠르게 함','速度をさらに速くすること。','人口減少が地域経済の縮小を加速させている。','인구 감소가 지역 경제의 축소를 가속하고 있다.'),
('n1-3262','2027-01-06','学会','がっかい','학회; 연구자들이 연구 발표와 교류를 하는 단체나 모임','研究者が成果を発表し、交流する団体や会合。','研究成果を国際学会で発表した。','연구 성과를 국제 학회에서 발표했다.'),
('n1-3263','2027-01-06','活字','かつじ','활자; 인쇄에 쓰는 글자; 인쇄된 문자','印刷に用いる文字。また、印刷された文字。','活字を読む習慣が思考力を育てる。','활자를 읽는 습관이 사고력을 기른다.'),
('n1-3264','2027-01-06','課程','かてい','과정; 교육기관에서 정한 학습 단계와 내용','教育機関で定められた学習の段階や内容。','所定の課程を修了すると資格を取得できる。','정해진 과정을 수료하면 자격을 취득할 수 있다.'),
('n1-3265','2027-01-06','加熱','かねつ','가열; 열을 가해 온도를 높임','熱を加えて温度を上げること。','食品は中心まで十分に加熱してください。','식품은 중심부까지 충분히 가열해 주세요.'),
('n1-3266','2027-01-06','貨物','かもつ','화물; 운송하는 짐이나 상품','運送の対象となる荷物や商品。','鉄道による貨物輸送の需要が高まっている。','철도를 이용한 화물 운송 수요가 높아지고 있다.'),
('n1-3267','2027-01-06','換気','かんき','환기; 실내 공기를 바깥 공기와 바꿈','室内の空気を外の新鮮な空気と入れ替えること。','感染対策として定期的に換気を行う。','감염 대책으로 정기적으로 환기한다.'),
('n1-3268','2027-01-06','気圧','きあつ','기압; 공기가 누르는 압력','空気が物体や地表を押す圧力。','気圧の低下に伴って天候が崩れた。','기압 저하에 따라 날씨가 나빠졌다.'),
('n1-3269','2027-01-06','気体','きたい','기체; 일정한 모양과 부피가 없는 물질 상태','一定の形や体積を持たない物質の状態。','液体が蒸発すると気体に変化する。','액체가 증발하면 기체로 변한다.'),
('n1-3270','2027-01-06','休講','きゅうこう','휴강; 예정된 강의를 쉼','予定されていた講義を休みにすること。','台風の接近により午後の授業は休講となった。','태풍 접근으로 오후 수업은 휴강이 되었다.'),
('n1-3271','2027-01-06','休息','きゅうそく','휴식; 하던 일을 멈추고 몸과 마음을 쉼','活動を止めて、心身を休めること。','長時間の作業では適度な休息が必要だ。','장시간 작업에는 적당한 휴식이 필요하다.'),
('n1-3272','2027-01-06','行列','ぎょうれつ','행렬; 줄을 지어 늘어선 사람이나 것; 수학의 행렬','人や物が列を作って並ぶこと。また、数学のマトリックス。','開店前から入口に長い行列ができた。','개점 전부터 입구에 긴 행렬이 생겼다.'),
('n1-3273','2027-01-06','曲線','きょくせん','곡선; 굽어 있는 선','まっすぐではなく、滑らかに曲がった線。','売上の変化を曲線で示した。','매출 변화를 곡선으로 나타냈다.'),
('n1-3274','2027-01-06','空中','くうちゅう','공중; 땅에서 떨어진 공간','地面から離れた空間。','空中に浮かぶ微粒子を測定した。','공중에 떠 있는 미세 입자를 측정했다.'),
('n1-3275','2027-01-06','原産','げんさん','원산; 동식물이나 생산물의 최초 산지','動植物や生産物が最初に生じた土地。','この植物は南米原産だとされている。','이 식물은 남미 원산으로 알려져 있다.'),
('n1-3276','2027-01-06','県庁','けんちょう','현청; 일본 현의 행정 사무를 담당하는 기관','県の行政事務を担当する役所。','申請書を県庁の担当窓口へ提出した。','신청서를 현청 담당 창구에 제출했다.'),
('n1-3277','2027-01-06','光線','こうせん','광선; 빛이 진행하는 선이나 빛줄기','光が進む道筋、または細い光の束。','強い光線から目を守る装備が必要だ。','강한 광선으로부터 눈을 보호하는 장비가 필요하다.'),
('n1-3278','2027-01-06','耕地','こうち','경지; 농작물을 재배하도록 일군 땅','農作物を育てるために耕された土地。','都市化によって周辺の耕地が減少している。','도시화로 주변 경지가 감소하고 있다.'),
('n1-3279','2027-01-06','鉱物','こうぶつ','광물; 지각 속에서 자연적으로 생성된 무기물','地殻中で自然に形成された無機物。','この地域では希少な鉱物が採掘される。','이 지역에서는 희귀한 광물이 채굴된다.'),
('n1-3280','2027-01-06','作者','さくしゃ','작자; 작품을 만든 사람','文学や芸術などの作品を作った人。','作品の背景を理解するため作者の経歴を調べた。','작품의 배경을 이해하기 위해 작자의 경력을 조사했다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2026-12-24..2027-01-06' FROM _n1_b7_words_0122 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b7_map_0122(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b7_words_0122 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
