INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3001","prompt":"「概論」の読み方として最も適切なものを選びなさい。","options":["きそ","さくいん","じつりょく","がいろん"],"answer":"がいろん","explanationKo":"「概論」는 「がいろん」라고 읽는다. 뜻은 개론; 전체 내용을 간추린 설명이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3002","prompt":"「規律」の読み方として最も適切なものを選びなさい。","options":["げんりょう","しゅうへん","きりつ","かつりょく"],"answer":"きりつ","explanationKo":"「規律」는 「きりつ」라고 읽는다. 뜻은 규율; 질서를 유지하기 위한 규칙이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3003","prompt":"「系統」の読み方として最も適切なものを選びなさい。","options":["だいがくいん","けいとう","じつれい","かんそう"],"answer":"けいとう","explanationKo":"「系統」는 「けいとう」라고 읽는다. 뜻은 계통; 체계; 같은 갈래이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3004","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）に携わる者には高い倫理意識が求められる。","options":["公務","性別","課程","侵入"],"answer":"公務","explanationKo":"문맥상 「公務」가 가장 자연스럽다. 공무; 국가나 지방자치단체의 업무라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3005","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの素材は熱を通しにくい（　）を持っている。","options":["評論","拡張","就任","性質"],"answer":"性質","explanationKo":"문맥상 「性質」가 가장 자연스럽다. 성질; 사물이나 사람의 고유한 특성라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3006","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新型端末は処理（　）と省電力性の両方が向上した。","options":["回答","集合","性能","執筆"],"answer":"性能","explanationKo":"문맥상 「性能」가 가장 자연스럽다. 성능; 기계 등이 발휘할 수 있는 능력라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3007","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n権力の集中が（　）につながらない仕組みが必要だ。","options":["体制","専制","家屋","空中"],"answer":"専制","explanationKo":"문맥상 「専制」가 가장 자연스럽다. 전제; 권력을 독점하여 마음대로 지배함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3008","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n被害を最小限に抑えるため、早急な（　）を講じた。","options":["対策","能率","学術","公式"],"answer":"対策","explanationKo":"문맥상 「対策」가 가장 자연스럽다. 대책; 문제에 대응하기 위한 방법라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3009","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n緊急時にも対応できる支援（　）を整えた。","options":["原稿","焦点","恩恵","体制"],"answer":"体制","explanationKo":"문맥상 「体制」가 가장 자연스럽다. 체제; 조직적으로 대응하는 구조라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3010","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n手順を見直した結果、作業の（　）が大幅に上がった。","options":["娯楽","商社","能率","運河"],"answer":"能率","explanationKo":"문맥상 「能率」가 가장 자연스럽다. 능률; 일정 시간에 이루는 작업의 효율라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3011","prompt":"「物事の価値や問題点を分析し、論じること。」という意味に最も近い語を選びなさい。","options":["研修","評論","引力","恩恵"],"answer":"評論","explanationKo":"「評論」의 핵심 의미는 평론; 가치나 문제점을 분석하여 논함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3012","prompt":"「一定の規則や周期に従っていないこと。」という意味に最も近い語を選びなさい。","options":["不規則","純情","一流","下品"],"answer":"不規則","explanationKo":"「不規則」의 핵심 의미는 불규칙; 일정한 규칙이 없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3013","prompt":"「自然現象や変化を継続的に観察し、測定すること。」という意味に最も近い語を選びなさい。","options":["各地","実物","私立","観測"],"answer":"観測","explanationKo":"「観測」의 핵심 의미는 관측; 현상이나 변화를 살펴 측정함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3014","prompt":"「物事について心に抱く考えや意識。」という意味に最も近い語を選びなさい。","options":["研修","乾燥","観念","省略"],"answer":"観念","explanationKo":"「観念」의 핵심 의미는 관념; 어떤 대상에 대해 마음속에 형성된 생각이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3015","prompt":"「物事を早く行うよう相手に求めること。」という意味に最も近い語を選びなさい。","options":["仮定","催促","学部","観測"],"answer":"催促","explanationKo":"「催促」의 핵심 의미는 재촉; 빨리 처리하도록 독촉함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','grammar',1,'〜からして','{"pattern":"〜からして","meaningKo":"〜부터가; 〜만 보아도","explanation":"〜からして는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"説明の冒頭からして曖昧で、計画全体への不安が残った。","ko":"문맥에서 〜부터가; 〜만 보아도의 의미로 쓰였다."},{"ja":"責任者の態度からして、事態の深刻さがうかがえる。","ko":"이 문장도 〜부터가; 〜만 보아도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','grammar',2,'〜くらいなら','{"pattern":"〜くらいなら","meaningKo":"〜할 바에는","explanation":"〜くらいなら는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"根拠のない結論を急いで出すくらいなら、調査を続けた方がよい。","ko":"문맥에서 〜할 바에는의 의미로 쓰였다."},{"ja":"品質を落としてまで納期を守るくらいなら、計画を見直すべきだ。","ko":"이 문장도 〜할 바에는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n説明の冒頭（　）曖昧で、計画全体への不安が残った。","options":["〜からして","〜ては〜ては","〜とはいうものの","〜はおろか"],"answer":"〜からして","explanationKo":"문맥상 〜부터가; 〜만 보아도를 나타내는 「〜からして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n根拠のない結論を急いで出す（　）、調査を続けた方がよい。","options":["〜てはじめて","〜とまではいかないが","〜はさておき","〜くらいなら"],"answer":"〜くらいなら","explanationKo":"문맥상 〜할 바에는를 나타내는 「〜くらいなら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n結果を待た（　）、現状から一定の傾向は読み取れる。","options":["〜に至る","〜ばかりに","〜ずとも","〜てはいられない"],"answer":"〜ずとも","explanationKo":"문맥상 〜하지 않아도를 나타내는 「〜ずとも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-24','reading',1,'相関を因果とみなさない','{"passage":"二つの現象の関連を分析することには、見落としていた変化の手掛かりを得られることという利点がある。もっとも、同時に起きたというだけで原因と結果を断定すると誤ることには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、第三の要因と時間的な順序も検討することが重要なのである。","questions":[{"prompt":"「相関を因果とみなさない」について筆者が最も重視していることは何か。","options":["第三の要因と時間的な順序も検討すること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"第三の要因と時間的な順序も検討すること","explanationKo":"본문에서는 第三の要因と時間的な順序も検討すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["同時に起きたというだけで原因と結果を断定すると誤ること","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"同時に起きたというだけで原因と結果を断定すると誤ること","explanationKo":"주의할 점은 同時に起きたというだけで原因と結果を断定すると誤ること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["見落としていた変化の手掛かりを得られること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"見落としていた変化の手掛かりを得られること","explanationKo":"二つの現象の関連を分析すること에는 見落としていた変化の手掛かりを得られること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3021","prompt":"「統計」の読み方として最も適切なものを選びなさい。","options":["とうけい","かざん","ひょうろん","かくちょう"],"answer":"とうけい","explanationKo":"「統計」는 「とうけい」라고 읽는다. 뜻은 통계; 자료를 수집·정리하여 수치로 나타낸 것이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3022","prompt":"「免税」の読み方として最も適切なものを選びなさい。","options":["しゅっちょう","きぐ","せいべつ","めんぜい"],"answer":"めんぜい","explanationKo":"「免税」는 「めんぜい」라고 읽는다. 뜻은 면세; 세금 부과를 면제함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3023","prompt":"「消極的」の読み方として最も適切なものを選びなさい。","options":["かくべつ","つとめる","しょうきょくてき","ふきそく"],"answer":"しょうきょくてき","explanationKo":"「消極的」는 「しょうきょくてき」라고 읽는다. 뜻은 소극적; 스스로 적극적으로 나서지 않는 모습이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3024","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの地域は冬でも（　）暖かい。","options":["幾分","比較的","始終","一旦"],"answer":"比較的","explanationKo":"문맥상 「比較的」가 가장 자연스럽다. 비교적; 다른 것과 비교해 보아 상대적으로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3025","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n標本数が少ないため、結果が偶然である（　）も考慮した。","options":["確率","実用","原稿","焦点"],"answer":"確率","explanationKo":"문맥상 「確率」가 가장 자연스럽다. 확률; 어떤 일이 일어날 가능성을 나타내는 수치라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3026","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n情報漏えいを防ぐため、認証機能を（　）した。","options":["混合","無沙汰","体制","強化"],"answer":"強化","explanationKo":"문맥상 「強化」가 가장 자연스럽다. 강화; 더 강하고 효과적으로 만듦라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3027","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの調査には地域の課題を明らかにする（　）がある。","options":["寿命","行事","意義","高層"],"answer":"意義","explanationKo":"문맥상 「意義」가 가장 자연스럽다. 의의; 어떤 일이나 행위가 지닌 가치와 중요성라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3028","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n基礎理論を実際の開発に（　）する。","options":["実力","応用","基盤","自治"],"answer":"応用","explanationKo":"문맥상 「応用」가 가장 자연스럽다. 응용; 원리나 지식을 다른 상황에 적용함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3029","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事故が重大な（　）によるものか調査が進められている。","options":["過失","行列","強化","謙遜"],"answer":"過失","explanationKo":"문맥상 「過失」가 가장 자연스럽다. 과실; 주의를 게을리하여 생긴 잘못라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3030","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n審査（　）を明確にし、手続きの透明性を高めた。","options":["区分","省略","研修","基準"],"answer":"基準","explanationKo":"문맥상 「基準」가 가장 자연스럽다. 기준; 판단하거나 비교할 때 근거가 되는 것라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3031","prompt":"「物事が成り立つ根本的な法則や仕組み。」という意味に最も近い語を選びなさい。","options":["消毒","概論","原理","鑑賞"],"answer":"原理","explanationKo":"「原理」의 핵심 의미는 원리; 현상이나 작용의 근본 법칙이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3032","prompt":"「産業活動などによって環境や住民に生じる社会的な害。」という意味に最も近い語を選びなさい。","options":["基礎","公害","換気","過失"],"answer":"公害","explanationKo":"「公害」의 핵심 의미는 공해; 산업 활동 등으로 환경과 주민에게 생기는 피해이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3033","prompt":"「社会や組織に貢献した優れた成果。」という意味に最も近い語を選びなさい。","options":["功績","間接","国籍","活力"],"answer":"功績","explanationKo":"「功績」의 핵심 의미는 공적; 어떤 분야에 기여한 뛰어난 성과이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3034","prompt":"「道理や論理にかなっていること。」という意味に最も近い語を選びなさい。","options":["総理大臣","敬語","実例","合理"],"answer":"合理","explanationKo":"「合理」의 핵심 의미는 합리; 이치나 논리에 맞음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3035","prompt":"「効果を及ぼす力、または法律上の有効性。」という意味に最も近い語を選びなさい。","options":["職人","性別","効力","姿勢"],"answer":"効力","explanationKo":"「効力」의 핵심 의미는 효력; 효과를 발휘하는 힘이나 법적 유효성이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','grammar',1,'〜ずとも','{"pattern":"〜ずとも","meaningKo":"〜하지 않아도","explanation":"〜ずとも는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"詳しく説明せずとも、図を見れば仕組みは理解できる。","ko":"문맥에서 〜하지 않아도의 의미로 쓰였다."},{"ja":"結果を待たずとも、現状から一定の傾向は読み取れる。","ko":"이 문장도 〜하지 않아도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','grammar',2,'〜たりとも〜ない','{"pattern":"〜たりとも〜ない","meaningKo":"단 한 〜도 〜않다","explanation":"〜たりとも〜ない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"機密情報は一文字たりとも外部に漏らしてはならない。","ko":"문맥에서 단 한 〜도 〜않다의 의미로 쓰였다."},{"ja":"作業中は一瞬たりとも警戒を緩められない。","ko":"이 문장도 단 한 〜도 〜않다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n詳しく説明せ（　）、図を見れば仕組みは理解できる。","options":["〜てはいられない","〜に至る","〜ばかりに","〜ずとも"],"answer":"〜ずとも","explanationKo":"문맥상 〜하지 않아도를 나타내는 「〜ずとも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n機密情報は（　）。","options":["〜に至るまで","〜べくして","〜たりとも〜ない","〜てばかりはいられない"],"answer":"〜たりとも〜ない","explanationKo":"문맥상 단 한 〜도 〜않다를 나타내는 「〜たりとも〜ない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）、異常があれば直ちに対応する。","options":["〜までだ","〜だろうが〜だろうが","〜ところを","〜にあっては"],"answer":"〜だろうが〜だろうが","explanationKo":"문맥상 〜이든 〜이든 상관없이를 나타내는 「〜だろうが〜だろうが」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-25','reading',1,'平均値の外側を見る','{"passage":"集団の特徴を数値で要約することには、全体のおおよその傾向を把握できることという利点がある。もっとも、平均だけでは一部に集中した負担や格差が隠れることには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、分布と例外を平均値と併せて確認することが重要なのである。","questions":[{"prompt":"「平均値の外側を見る」について筆者が最も重視していることは何か。","options":["分布と例外を平均値と併せて確認すること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"分布と例外を平均値と併せて確認すること","explanationKo":"본문에서는 分布と例外を平均値と併せて確認すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["平均だけでは一部に集中した負担や格差が隠れること","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"平均だけでは一部に集中した負担や格差が隠れること","explanationKo":"주의할 점은 平均だけでは一部に集中した負担や格差が隠れること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["全体のおおよその傾向を把握できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"全体のおおよその傾向を把握できること","explanationKo":"集団の特徴を数値で要約すること에는 全体のおおよその傾向を把握できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3041","prompt":"「過半数」の読み方として最も適切なものを選びなさい。","options":["げんこう","かはんすう","せいしつ","じっせき"],"answer":"かはんすう","explanationKo":"「過半数」는 「かはんすう」라고 읽는다. 뜻은 과반수; 전체의 절반을 넘는 수이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3042","prompt":"「移転」の読み方として最も適切なものを選びなさい。","options":["いてん","えんちょう","こんごう","ぶさた"],"answer":"いてん","explanationKo":"「移転」는 「いてん」라고 읽는다. 뜻은 이전; 장소나 권리 등을 다른 곳으로 옮김이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3043","prompt":"「有無」の読み方として最も適切なものを選びなさい。","options":["じゅうりょく","こうそう","じゅみょう","うむ"],"answer":"うむ","explanationKo":"「有無」는 「うむ」라고 읽는다. 뜻은 유무; 있음과 없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3044","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n専門家が制度変更の要点を詳しく（　）した。","options":["基盤","自治","解説","原理"],"answer":"解説","explanationKo":"문맥상 「解説」가 가장 자연스럽다. 해설; 내용을 알기 쉽게 설명함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3045","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n古い建物を（　）して交流施設として活用している。","options":["各地","改造","個体","活力"],"answer":"改造","explanationKo":"문맥상 「改造」가 가장 자연스럽다. 개조; 기존 구조를 고쳐 다른 형태나 기능으로 만듦라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3046","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長時間の緊張から（　）され、ようやく安心した。","options":["解放","回答","敷地","正面"],"answer":"解放","explanationKo":"문맥상 「解放」가 가장 자연스럽다. 해방; 속박이나 제한에서 벗어나게 함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3047","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n自治体は子育て支援制度の（　）を進めている。","options":["商社","青少年","学部","拡充"],"answer":"拡充","explanationKo":"문맥상 「拡充」가 가장 자연스럽다. 확충; 규모나 내용을 넓혀 충실하게 함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3048","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n研究成果は国際的な（　）誌に掲載された。","options":["換気","過失","学術","終了"],"answer":"学術","explanationKo":"문맥상 「学術」가 가장 자연스럽다. 학술; 전문적인 학문과 연구라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3049","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者の増加に備えてサーバー容量を（　）した。","options":["工夫","拡張","解説","指定"],"answer":"拡張","explanationKo":"문맥상 「拡張」가 가장 자연스럽다. 확장; 범위나 규모, 기능을 넓힘라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3050","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n予算案は賛成多数で（　）された。","options":["可決","下降","出勤","休講"],"answer":"可決","explanationKo":"문맥상 「可決」가 가장 자연스럽다. 가결; 의안이 찬성을 얻어 통과됨라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3051","prompt":"「必要な程度を超えて多すぎること。」という意味に最も近い語を選びなさい。","options":["的確","高級","論ずる","過剰"],"answer":"過剰","explanationKo":"「過剰」의 핵심 의미는 과잉; 필요한 정도를 지나치게 넘음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3052","prompt":"「税金を割り当てて負担させること。」という意味に最も近い語を選びなさい。","options":["原始","焦点","課税","過半数"],"answer":"課税","explanationKo":"「課税」의 핵심 의미는 과세; 세금을 부과함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3053","prompt":"「事実かどうか未確定のことを、ひとまずそうだと定めること。」という意味に最も近い語を選びなさい。","options":["公衆","仮定","重点","運河"],"answer":"仮定","explanationKo":"「仮定」의 핵심 의미는 가정; 사실인지 확정되지 않은 것을 임시로 설정함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3054","prompt":"「物事が進行して結果に至るまでの道筋。」という意味に最も近い語を選びなさい。","options":["過程","改正","作成","開通"],"answer":"過程","explanationKo":"「過程」의 핵심 의미는 과정; 일이 진행되어 결과에 이르는 경로이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3055","prompt":"「現金を直接送らずに決済する仕組み。また、通貨の交換比率。」という意味に最も近い語を選びなさい。","options":["往復","合流","苦心","為替"],"answer":"為替","explanationKo":"「為替」의 핵심 의미는 환; 환율; 현금을 직접 보내지 않고 결제하는 제도이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','grammar',1,'〜だろうが〜だろうが','{"pattern":"〜だろうが〜だろうが","meaningKo":"〜이든 〜이든 상관없이","explanation":"〜だろうが〜だろうが는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"賛成だろうが反対だろうが、まず根拠を示してほしい。","ko":"문맥에서 〜이든 〜이든 상관없이의 의미로 쓰였다."},{"ja":"平日だろうが休日だろうが、異常があれば直ちに対応する。","ko":"이 문장도 〜이든 〜이든 상관없이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','grammar',2,'〜ては〜ては','{"pattern":"〜ては〜ては","meaningKo":"계속 〜하고 또 〜하다","explanation":"〜ては〜ては는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"書いては消し、書いては消しを繰り返して、ようやく案をまとめた。","ko":"문맥에서 계속 〜하고 또 〜하다의 의미로 쓰였다."},{"ja":"試しては直し、試しては直しながら精度を高めた。","ko":"이 문장도 계속 〜하고 또 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）、まず根拠を示してほしい。","options":["〜にあっては","〜までだ","〜だろうが〜だろうが","〜ところを"],"answer":"〜だろうが〜だろうが","explanationKo":"문맥상 〜이든 〜이든 상관없이를 나타내는 「〜だろうが〜だろうが」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）を繰り返して、ようやく案をまとめた。","options":["〜までのことだ","〜ては〜ては","〜とはいえ","〜にかけては"],"answer":"〜ては〜ては","explanationKo":"문맥상 계속 〜하고 또 〜하다를 나타내는 「〜ては〜ては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n異なる立場の意見を聞い（　）、判断の偏りを自覚した。","options":["〜てはじめて","〜とはいうものの","〜にせよ〜にせよ","〜を契機に"],"answer":"〜てはじめて","explanationKo":"문맥상 〜하고 나서야 비로소를 나타내는 「〜てはじめて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-26','reading',1,'制度を使えない人を捉える','{"passage":"支援制度の利用状況を調べることには、制度が届いている範囲を評価できることという利点がある。もっとも、申請者だけを調べると利用を断念した人が見えないことには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、利用前に生じる情報と手続きの障壁も調査することが重要なのである。","questions":[{"prompt":"「制度を使えない人を捉える」について筆者が最も重視していることは何か。","options":["利用前に生じる情報と手続きの障壁も調査すること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"利用前に生じる情報と手続きの障壁も調査すること","explanationKo":"본문에서는 利用前に生じる情報と手続きの障壁も調査すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["申請者だけを調べると利用を断念した人が見えないこと","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"申請者だけを調べると利用を断念した人が見えないこと","explanationKo":"주의할 점은 申請者だけを調べると利用を断念した人が見えないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["制度が届いている範囲を評価できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"制度が届いている範囲を評価できること","explanationKo":"支援制度の利用状況を調べること에는 制度が届いている範囲を評価できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3061","prompt":"「基盤」の読み方として最も適切なものを選びなさい。","options":["ちかすい","ぎょうれつ","きばん","ききん"],"answer":"きばん","explanationKo":"「基盤」는 「きばん」라고 읽는다. 뜻은 기반; 활동이나 발전을 떠받치는 토대이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3062","prompt":"「境界」の読み方として最も適切なものを選びなさい。","options":["くぶん","きょうかい","かもつ","せいさく"],"answer":"きょうかい","explanationKo":"「境界」는 「きょうかい」라고 읽는다. 뜻은 경계; 영역과 영역을 가르는 선이나 지점이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3063","prompt":"「教養」の読み方として最も適切なものを選びなさい。","options":["きょうよう","かけつ","しゅくしょう","かんしょう"],"answer":"きょうよう","explanationKo":"「教養」는 「きょうよう」라고 읽는다. 뜻은 교양; 폭넓은 지식과 판단력을 기르는 소양이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3064","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの（　）では建物の高さが制限されている。","options":["開放","終了","換気","区域"],"answer":"区域","explanationKo":"문맥상 「区域」가 가장 자연스럽다. 구역; 일정한 기준으로 나눈 범위라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3065","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n所得の（　）によって必要な書類が異なる。","options":["解説","指定","区分","原産"],"answer":"区分","explanationKo":"문맥상 「区分」가 가장 자연스럽다. 구분; 기준에 따라 나누는 일이나 그 범주라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3066","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n報告書は指定された（　）で提出してください。","options":["総理大臣","形式","学術","口実"],"answer":"形式","explanationKo":"문맥상 「形式」가 가장 자연스럽다. 형식; 일정하게 정해진 방식이나 모양라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3067","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n支援を（　）するには安定した財源が必要だ。","options":["継続","実習","加速","抽象"],"answer":"継続","explanationKo":"문맥상 「継続」가 가장 자연스럽다. 계속; 이전부터 해 오던 일을 이어감라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3068","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n問い合わせが（　）し、窓口の対応が追いつかない。","options":["能率","過半数","原始","激増"],"answer":"激増","explanationKo":"문맥상 「激増」가 가장 자연스럽다. 격증; 수량이 급격히 늘어남라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3069","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n景気が回復する（　）はまだ見られない。","options":["家屋","鉱物","気配","漁業"],"answer":"気配","explanationKo":"문맥상 「気配」가 가장 자연스럽다. 기미; 어떤 일이 일어나려는 낌새나 분위기라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3070","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n批判にも（　）に耳を傾ける姿勢が大切だ。","options":["恐縮","謙虚","架空","厳重"],"answer":"謙虚","explanationKo":"문맥상 「謙虚」가 가장 자연스럽다. 겸허; 자신을 내세우지 않고 남의 의견을 받아들이는 태도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3071","prompt":"「発表や印刷のために書いた文章。」という意味に最も近い語を選びなさい。","options":["原稿","肯定","往復","合流"],"answer":"原稿","explanationKo":"「原稿」의 핵심 의미는 원고; 발표나 출판을 위해 작성한 글이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3072","prompt":"「物事や社会が発達する前の、最も初期の状態。」という意味に最も近い語を選びなさい。","options":["交差","休業","性質","原始"],"answer":"原始","explanationKo":"「原始」의 핵심 의미는 원시; 사물이나 사회의 가장 처음 단계이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3073","prompt":"「非常に厳しく、注意が行き届いているさま。」という意味に最も近い語を選びなさい。","options":["架空","謙虚","厳重","案外"],"answer":"厳重","explanationKo":"「厳重」의 핵심 의미는 엄중; 매우 엄격하고 빈틈이 없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3074","prompt":"「自分の能力や価値を控えめに評価して言うこと。」という意味に最も近い語を選びなさい。","options":["休養","謙遜","循環","交替"],"answer":"謙遜","explanationKo":"「謙遜」의 핵심 의미는 겸손; 자신의 능력이나 가치를 낮추어 말함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3075","prompt":"「社会全体や多くの人々に共通して関わること。」という意味に最も近い語を選びなさい。","options":["公共","芸能","工芸","重体"],"answer":"公共","explanationKo":"「公共」의 핵심 의미는 공공; 사회 전체 또는 여러 사람이 함께 관계되는 것이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','grammar',1,'〜てはじめて','{"pattern":"〜てはじめて","meaningKo":"〜하고 나서야 비로소","explanation":"〜てはじめて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"実際に運用してはじめて、設計上の問題に気づいた。","ko":"문맥에서 〜하고 나서야 비로소의 의미로 쓰였다."},{"ja":"異なる立場の意見を聞いてはじめて、判断の偏りを自覚した。","ko":"이 문장도 〜하고 나서야 비로소의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','grammar',2,'〜てはいられない','{"pattern":"〜てはいられない","meaningKo":"계속 〜하고 있을 수 없다","explanation":"〜てはいられない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"被害が広がっている以上、結論を待ってはいられない。","ko":"문맥에서 계속 〜하고 있을 수 없다의 의미로 쓰였다."},{"ja":"期限が迫っているので、迷ってはいられない。","ko":"이 문장도 계속 〜하고 있을 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n実際に運用し（　）、設計上の問題に気づいた。","options":["〜を契機に","〜てはじめて","〜とはいうものの","〜にせよ〜にせよ"],"answer":"〜てはじめて","explanationKo":"문맥상 〜하고 나서야 비로소를 나타내는 「〜てはじめて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n被害が広がっている以上、結論を待っ（　）。","options":["〜てはいられない","〜とまではいかないが","〜にひとしい","〜を境に"],"answer":"〜てはいられない","explanationKo":"문맥상 계속 〜하고 있을 수 없다를 나타내는 「〜てはいられない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n失敗を（　）ので、原因分析を始めた。","options":["〜に至る","〜はおろか","〜を抜きにして","〜てばかりはいられない"],"answer":"〜てばかりはいられない","explanationKo":"문맥상 계속 〜만 하고 있을 수 없다를 나타내는 「〜てばかりはいられない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-27','reading',1,'自動判断の境界を定める','{"passage":"機械による判定を業務に用いることには、大量の事例を一定の基準で処理できることという利点がある。もっとも、判定理由を確認できなければ誤りの修正が難しいことには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、人が再検討する条件と異議申立ての経路を設けることが重要なのである。","questions":[{"prompt":"「自動判断の境界を定める」について筆者が最も重視していることは何か。","options":["人が再検討する条件と異議申立ての経路を設けること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"人が再検討する条件と異議申立ての経路を設けること","explanationKo":"본문에서는 人が再検討する条件と異議申立ての経路を設けること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["判定理由を確認できなければ誤りの修正が難しいこと","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"判定理由を確認できなければ誤りの修正が難しいこと","explanationKo":"주의할 점은 判定理由を確認できなければ誤りの修正が難しいこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["大量の事例を一定の基準で処理できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"大量の事例を一定の基準で処理できること","explanationKo":"機械による判定を業務に用いること에는 大量の事例を一定の基準で処理できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3081","prompt":"「公表」の読み方として最も適切なものを選びなさい。","options":["えんげい","げんさん","かいせつ","こうひょう"],"answer":"こうひょう","explanationKo":"「公表」는 「こうひょう」라고 읽는다. 뜻은 공표; 여러 사람에게 공식적으로 알림이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3082","prompt":"「項目」の読み方として最も適切なものを選びなさい。","options":["がくじゅつ","こうしき","こうもく","のうりつ"],"answer":"こうもく","explanationKo":"「項目」는 「こうもく」라고 읽는다. 뜻은 항목; 내용을 나눈 각각의 사항이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3083","prompt":"「国籍」の読み方として最も適切なものを選びなさい。","options":["がいぶ","こくせき","げんこう","しぜんかがく"],"answer":"こくせき","explanationKo":"「国籍」는 「こくせき」라고 읽는다. 뜻은 국적; 특정 국가의 구성원인 법적 자격이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3084","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n同じ種類でも（　）によって特徴が異なる。","options":["個体","液体","雑音","勝敗"],"answer":"個体","explanationKo":"문맥상 「個体」가 가장 자연스럽다. 개체; 독립된 하나의 생물체나 물체라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3085","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）を現代の視点から読み直す授業を受けた。","options":["主役","漁業","家屋","古典"],"answer":"古典","explanationKo":"문맥상 「古典」가 가장 자연스럽다. 고전; 오랫동안 가치를 인정받아 온 작품라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3086","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）注意したにもかかわらず、同じ誤りが起きた。","options":["各自","比較的","再三","一段"],"answer":"再三","explanationKo":"문맥상 「再三」가 가장 자연스럽다. 재삼; 여러 차례 거듭하여라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3087","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n巻末の（　）を使って関連する用語を調べた。","options":["往復","索引","応用","肯定"],"answer":"索引","explanationKo":"문맥상 「索引」가 가장 자연스럽다. 색인; 필요한 내용을 찾도록 정리한 목록라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3088","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n不要な個人情報を記録から（　）した。","options":["削除","職人","性別","課程"],"answer":"削除","explanationKo":"문맥상 「削除」가 가장 자연스럽다. 삭제; 글이나 데이터를 지워 없앰라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3089","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n調査結果を基に報告書を（　）した。","options":["火山","催促","仮定","作成"],"answer":"作成","explanationKo":"문맥상 「作成」가 가장 자연스럽다. 작성; 문서나 자료 등을 만들어 완성함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3090","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n危険を避けるための（　）手段を身につける。","options":["循環","交替","自衛","拡張"],"answer":"自衛","explanationKo":"문맥상 「自衛」가 가장 자연스럽다. 자위; 스스로를 지키고 방어함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3091","prompt":"「地域や団体が自らの責任で運営し、治めること。」という意味に最も近い語を選びなさい。","options":["自衛","自治","課税","気配"],"answer":"自治","explanationKo":"「自治」의 핵심 의미는 자치; 지역이나 단체가 스스로 다스림이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3092","prompt":"「文章や書物を書くこと。」という意味に最も近い語を選びなさい。","options":["執筆","休息","意義","官庁"],"answer":"執筆","explanationKo":"「執筆」의 핵심 의미는 집필; 글이나 책을 씀이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3093","prompt":"「特定の物や条件を定めて示すこと。」という意味に最も近い語を選びなさい。","options":["為替","構造","総理大臣","指定"],"answer":"指定","explanationKo":"「指定」의 핵심 의미는 지정; 특정한 대상이나 조건을 정해 가리킴이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3094","prompt":"「建物などを支える土地。また、活動を支える基礎。」という意味に最も近い語を選びなさい。","options":["観測","可決","地盤","学会"],"answer":"地盤","explanationKo":"「地盤」의 핵심 의미는 지반; 건축물 등을 지탱하는 땅; 활동의 기반이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3095","prompt":"「紙で作られた通貨。」という意味に最も近い語を選びなさい。","options":["開放","紙幣","解放","指定"],"answer":"紙幣","explanationKo":"「紙幣」의 핵심 의미는 지폐; 종이로 만든 화폐이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','grammar',1,'〜てばかりはいられない','{"pattern":"〜てばかりはいられない","meaningKo":"계속 〜만 하고 있을 수 없다","explanation":"〜てばかりはいられない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"過去の成功に頼ってばかりはいられない。","ko":"문맥에서 계속 〜만 하고 있을 수 없다의 의미로 쓰였다."},{"ja":"失敗を悔やんでばかりはいられないので、原因分析を始めた。","ko":"이 문장도 계속 〜만 하고 있을 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','grammar',2,'〜ところを','{"pattern":"〜ところを","meaningKo":"〜한 상황인데도; 〜한 중에","explanation":"〜ところを는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"お忙しいところを、ご確認いただきありがとうございます。","ko":"문맥에서 〜한 상황인데도; 〜한 중에의 의미로 쓰였다."},{"ja":"本来なら休めるところを、緊急対応に協力してもらった。","ko":"이 문장도 〜한 상황인데도; 〜한 중에의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n過去の成功に頼っ（　）。","options":["〜てばかりはいられない","〜に至る","〜はおろか","〜を抜きにして"],"answer":"〜てばかりはいられない","explanationKo":"문맥상 계속 〜만 하고 있을 수 없다를 나타내는 「〜てばかりはいられない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nお忙しい（　）、ご確認いただきありがとうございます。","options":["〜に至るまで","〜はさておき","〜からして","〜ところを"],"answer":"〜ところを","explanationKo":"문맥상 〜한 상황인데도; 〜한 중에를 나타내는 「〜ところを」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n専門家（　）、すべてを正確に予測できるわけではない。","options":["〜ばかりに","〜くらいなら","〜とはいえ","〜にあっては"],"answer":"〜とはいえ","explanationKo":"문맥상 〜라고는 해도를 나타내는 「〜とはいえ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-28','reading',1,'保存しない情報を決める','{"passage":"将来に備えて資料を保存することには、過去の判断や変化を検証できることという利点がある。もっとも、すべてを残すと重要な情報の発見と管理が難しくなることには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、保存目的と期限を定めて不要な情報を整理することが重要なのである。","questions":[{"prompt":"「保存しない情報を決める」について筆者が最も重視していることは何か。","options":["保存目的と期限を定めて不要な情報を整理すること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"保存目的と期限を定めて不要な情報を整理すること","explanationKo":"본문에서는 保存目的と期限を定めて不要な情報を整理すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["すべてを残すと重要な情報の発見と管理が難しくなること","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"すべてを残すと重要な情報の発見と管理が難しくなること","explanationKo":"주의할 점은 すべてを残すと重要な情報の発見と管理が難しくなること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["過去の判断や変化を検証できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"過去の判断や変化を検証できること","explanationKo":"将来に備えて資料を保存すること에는 過去の判断や変化を検証できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3101","prompt":"「縮小」の読み方として最も適切なものを選びなさい。","options":["しゅくしょう","せんせい","こうりょく","けいしき"],"answer":"しゅくしょう","explanationKo":"「縮小」는 「しゅくしょう」라고 읽는다. 뜻은 축소; 규모나 범위를 줄임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3102","prompt":"「循環」の読み方として最も適切なものを選びなさい。","options":["きょうかい","じばん","じゅうりょく","じゅんかん"],"answer":"じゅんかん","explanationKo":"「循環」는 「じゅんかん」라고 읽는다. 뜻은 순환; 일정한 경로를 따라 되풀이해 돎이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3103","prompt":"「順序」の読み方として最も適切なものを選びなさい。","options":["おうよう","こうてい","じゅんじょ","きょくせん"],"answer":"じゅんじょ","explanationKo":"「順序」는 「じゅんじょ」라고 읽는다. 뜻은 순서; 일을 진행하거나 배열하는 차례이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3104","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は（　）な好奇心から研究を始めた。","options":["的確","純粋","強引","公正"],"answer":"純粋","explanationKo":"문맥상 「純粋」가 가장 자연스럽다. 순수; 다른 것이 섞이지 않음; 사심이 없음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3105","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n議論の（　）は費用負担の公平性に移った。","options":["焦点","工夫","蒸発","規律"],"answer":"焦点","explanationKo":"문맥상 「焦点」가 가장 자연스럽다. 초점; 관심이나 논의가 집중되는 중심라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3106","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長時間の交渉で双方とも精神的に（　）した。","options":["鉱物","拡張","縮小","消耗"],"answer":"消耗","explanationKo":"문맥상 「消耗」가 가장 자연스럽다. 소모; 사용하여 줄어들거나 기력이 쇠함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3107","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n繰り返しとなる説明は（　）した。","options":["警備","感激","省略","指定"],"answer":"省略","explanationKo":"문맥상 「省略」가 가장 자연스럽다. 생략; 일부를 줄이거나 빼버림라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3108","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）では観測と実験が重要な役割を果たす。","options":["弱点","自然科学","引力","傑作"],"answer":"自然科学","explanationKo":"문맥상 「自然科学」가 가장 자연스럽다. 자연과학; 자연 현상을 연구하는 학문라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3109","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の視点から人口減少の要因を分析する。","options":["社会科学","子孫","書籍","加速度"],"answer":"社会科学","explanationKo":"문맥상 「社会科学」가 가장 자연스럽다. 사회과학; 사회 현상과 제도를 연구하는 학문라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3110","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の研究では文献の解釈が重視される。","options":["酸性","学会","観測","人文科学"],"answer":"人文科学","explanationKo":"문맥상 「人文科学」가 가장 자연스럽다. 인문과학; 인간의 사상·문화·역사를 연구하는 학문라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3111","prompt":"「日本の内閣を代表し、行政を統括する長。」という意味に最も近い語を選びなさい。","options":["解放","指定","総理大臣","作者"],"answer":"総理大臣","explanationKo":"「総理大臣」의 핵심 의미는 총리대신; 일본 내각의 수장이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3112","prompt":"「物体同士が互いに引き合う力。」という意味に最も近い語を選びなさい。","options":["持参","引力","自衛","回転"],"answer":"引力","explanationKo":"「引力」의 핵심 의미는 인력; 물체끼리 서로 끌어당기는 힘이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3113","prompt":"「学習によって身につけた知識や能力。」という意味に最も近い語を選びなさい。","options":["学力","混合","無沙汰","能率"],"answer":"学力","explanationKo":"「学力」의 핵심 의미는 학력; 학습을 통해 얻은 지식과 능력이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3114","prompt":"「元気に活動するための力や勢い。」という意味に最も近い語を選びなさい。","options":["性能","実用","原稿","活力"],"answer":"活力","explanationKo":"「活力」의 핵심 의미는 활력; 힘차게 활동하게 하는 에너지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3115","prompt":"「演劇、音楽、舞踊など、人前で演じる技芸。」という意味に最も近い語を選びなさい。","options":["重点","液体","芸能","区域"],"answer":"芸能","explanationKo":"「芸能」의 핵심 의미는 예능; 연극·음악·무용 등 사람 앞에서 보이는 기예이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','grammar',1,'〜とはいえ','{"pattern":"〜とはいえ","meaningKo":"〜라고는 해도","explanation":"〜とはいえ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"改善したとはいえ、まだ十分な水準には達していない。","ko":"문맥에서 〜라고는 해도의 의미로 쓰였다."},{"ja":"専門家とはいえ、すべてを正確に予測できるわけではない。","ko":"이 문장도 〜라고는 해도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','grammar',2,'〜とはいうものの','{"pattern":"〜とはいうものの","meaningKo":"〜라고는 하지만","explanation":"〜とはいうものの는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"制度は始まったとはいうものの、現場には十分浸透していない。","ko":"문맥에서 〜라고는 하지만의 의미로 쓰였다."},{"ja":"引き受けたとはいうものの、一人で終えられる量ではない。","ko":"이 문장도 〜라고는 하지만의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n改善した（　）、まだ十分な水準には達していない。","options":["〜にあっては","〜ばかりに","〜くらいなら","〜とはいえ"],"answer":"〜とはいえ","explanationKo":"문맥상 〜라고는 해도를 나타내는 「〜とはいえ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n制度は始まった（　）、現場には十分浸透していない。","options":["〜べくして","〜ずとも","〜とはいうものの","〜にかけては"],"answer":"〜とはいうものの","explanationKo":"문맥상 〜라고는 하지만를 나타내는 「〜とはいうものの」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n全面的な賛成（　）、提案の趣旨は理解できる。","options":["〜たりとも〜ない","〜とまではいかないが","〜にせよ〜にせよ","〜までだ"],"answer":"〜とまではいかないが","explanationKo":"문맥상 〜라고 할 정도는 아니지만를 나타내는 「〜とまではいかないが」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-29','reading',1,'標準化と地域差を両立する','{"passage":"共通の手順を複数の現場に導入することには、品質と説明の基準をそろえられることという利点がある。もっとも、地域の条件を無視すると手順が実態に合わなくなることには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、守るべき核心と現場で変更できる部分を分けることが重要なのである。","questions":[{"prompt":"「標準化と地域差を両立する」について筆者が最も重視していることは何か。","options":["守るべき核心と現場で変更できる部分を分けること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"守るべき核心と現場で変更できる部分を分けること","explanationKo":"본문에서는 守るべき核心と現場で変更できる部分を分けること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["地域の条件を無視すると手順が実態に合わなくなること","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"地域の条件を無視すると手順が実態に合わなくなること","explanationKo":"주의할 점은 地域の条件を無視すると手順が実態に合わなくなること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["品質と説明の基準をそろえられること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"品質と説明の基準をそろえられること","explanationKo":"共通の手順を複数の現場に導入すること에는 品質と説明の基準をそろえられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3121","prompt":"「務める」の読み方として最も適切なものを選びなさい。","options":["いってい","つとめる","てきかく","こうきゅう"],"answer":"つとめる","explanationKo":"「務める」는 「つとめる」라고 읽는다. 뜻은 맡다; 역할이나 직책을 담당하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3122","prompt":"「緩い」の読み方として最も適切なものを選びなさい。","options":["ゆるい","しきゅう","さいさん","いこう"],"answer":"ゆるい","explanationKo":"「緩い」는 「ゆるい」라고 읽는다. 뜻은 느슨하다; 엄격하지 않다; 완만하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3123","prompt":"「論ずる」の読み方として最も適切なものを選びなさい。","options":["こうど","かくう","つとめる","ろんずる"],"answer":"ろんずる","explanationKo":"「論ずる」는 「ろんずる」라고 읽는다. 뜻은 논하다; 근거를 들어 의견을 전개하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3124","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な判断で方針を変更すべきではない。","options":["的確","高級","安易","公正"],"answer":"安易","explanationKo":"문맥상 「安易」가 가장 자연스럽다. 안이; 깊이 생각하지 않고 쉽게 처리하려 함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3125","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n難しそうに見えたが、実際の作業は（　）簡単だった。","options":["厳重","案外","格別","論ずる"],"answer":"案外","explanationKo":"문맥상 「案外」가 가장 자연스럽다. 의외로; 예상과 달리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3126","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n説明を聞いて不安が（　）和らいだ。","options":["幾分","一旦","早速","始終"],"answer":"幾分","explanationKo":"문맥상 「幾分」가 가장 자연스럽다. 다소; 어느 정도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3127","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの事故（　）、安全基準が大幅に見直された。","options":["始終","再三","一応","以後"],"answer":"以後","explanationKo":"문맥상 「以後」가 가장 자연스럽다. 이후; 어떤 시점을 포함해 그 뒤라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3128","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n来月（　）の予定はまだ決まっていない。","options":["一応","一旦","以降","再三"],"answer":"以降","explanationKo":"문맥상 「以降」가 가장 자연스럽다. 이후; 기준이 되는 시점부터 뒤라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3129","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n提出前に（　）すべての項目を確認した。","options":["各自","一応","幾分","一段"],"answer":"一応","explanationKo":"문맥상 「一応」가 가장 자연스럽다. 일단; 완전하지는 않지만 필요한 정도로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3130","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度の改正によって利便性が（　）と高まった。","options":["一段","一応","各々","幾分"],"answer":"一段","explanationKo":"문맥상 「一段」가 가장 자연스럽다. 한층; 이전보다 더욱라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3131","prompt":"「技術や品質などが最も優れた部類。」という意味に最も近い語を選びなさい。","options":["的確","純情","架空","一流"],"answer":"一流","explanationKo":"「一流」의 핵심 의미는 일류; 수준이 가장 높은 부류이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3132","prompt":"「多くの人や物が同時に同じ動きをするさま。」という意味に最も近い語を選びなさい。","options":["幾分","一応","一斉","比較的"],"answer":"一斉","explanationKo":"「一斉」의 핵심 의미는 일제히; 많은 사람이 동시에 행동하는 모양이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3133","prompt":"「ひとまず一度。また、ある状態になった場合。」という意味に最も近い語を選びなさい。","options":["一斉","一旦","早速","以後"],"answer":"一旦","explanationKo":"「一旦」의 핵심 의미는 일단; 우선 잠시; 한번 어떤 상태가 되면이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3134","prompt":"「決まっていて変わらないこと。また、ある程度。」という意味に最も近い語を選びなさい。","options":["一定","公正","的確","純情"],"answer":"一定","explanationKo":"「一定」의 핵심 의미는 일정; 정해져 있어 변하지 않음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3135","prompt":"「商品やサービスを売って得た金額。」という意味に最も近い語を選びなさい。","options":["気圧","統一","継続","売上"],"answer":"売上","explanationKo":"「売上」의 핵심 의미는 매출; 상품이나 서비스를 판매해 얻은 금액이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','grammar',1,'〜とまではいかないが','{"pattern":"〜とまではいかないが","meaningKo":"〜라고 할 정도는 아니지만","explanation":"〜とまではいかないが는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"完璧とまではいかないが、実用に耐える水準には達した。","ko":"문맥에서 〜라고 할 정도는 아니지만의 의미로 쓰였다."},{"ja":"全面的な賛成とまではいかないが、提案の趣旨は理解できる。","ko":"이 문장도 〜라고 할 정도는 아니지만의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','grammar',2,'〜に至る','{"pattern":"〜に至る","meaningKo":"마침내 〜에 이르다","explanation":"〜に至る는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長い協議の末、双方が合意に至った。","ko":"문맥에서 마침내 〜에 이르다의 의미로 쓰였다."},{"ja":"複数の証拠を検討し、原因の特定に至った。","ko":"이 문장도 마침내 〜에 이르다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n完璧（　）、実用に耐える水準には達した。","options":["〜までだ","〜たりとも〜ない","〜とまではいかないが","〜にせよ〜にせよ"],"answer":"〜とまではいかないが","explanationKo":"문맥상 〜라고 할 정도는 아니지만를 나타내는 「〜とまではいかないが」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長い協議の末、双方が合意（　）。","options":["〜だろうが〜だろうが","〜に至る","〜にひとしい","〜までのことだ"],"answer":"〜に至る","explanationKo":"문맥상 마침내 〜에 이르다를 나타내는 「〜に至る」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n小さな部品（　）、安全基準を満たしているか確認した。","options":["〜に至るまで","〜はおろか","〜を契機に","〜ては〜ては"],"answer":"〜に至るまで","explanationKo":"문맥상 〜에 이르기까지를 나타내는 「〜に至るまで」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-30','reading',1,'警告を増やしすぎない','{"passage":"危険や誤操作を知らせる表示を設けることには、利用者が問題を早く認識できることという利点がある。もっとも、警告が多すぎると重要度の違いが分からなくなることには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、発生確率と影響に応じて警告の段階を設計することが重要なのである。","questions":[{"prompt":"「警告を増やしすぎない」について筆者が最も重視していることは何か。","options":["発生確率と影響に応じて警告の段階を設計すること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"発生確率と影響に応じて警告の段階を設計すること","explanationKo":"본문에서는 発生確率と影響に応じて警告の段階を設計すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["警告が多すぎると重要度の違いが分からなくなること","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"警告が多すぎると重要度の違いが分からなくなること","explanationKo":"주의할 점은 警告が多すぎると重要度の違いが分からなくなること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["利用者が問題を早く認識できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"利用者が問題を早く認識できること","explanationKo":"危険や誤操作を知らせる表示を設けること에는 利用者が問題を早く認識できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3141","prompt":"「応対」の読み方として最も適切なものを選びなさい。","options":["かねつ","とうけい","おうたい","しゅうごう"],"answer":"おうたい","explanationKo":"「応対」는 「おうたい」라고 읽는다. 뜻은 응대; 상대의 말이나 요구에 맞추어 대응함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3142","prompt":"「往復」の読み方として最も適切なものを選びなさい。","options":["かいてん","おうふく","しゃせつ","かつりょく"],"answer":"おうふく","explanationKo":"「往復」는 「おうふく」라고 읽는다. 뜻은 왕복; 갔다가 돌아옴이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3143","prompt":"「欧米」の読み方として最も適切なものを選びなさい。","options":["おうべい","かいつう","げんりょう","しきち"],"answer":"おうべい","explanationKo":"「欧米」는 「おうべい」라고 읽는다. 뜻은 구미; 유럽과 미국이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3144","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n参加者が（　）の立場から意見を述べた。","options":["以後","一段","早速","各々"],"answer":"各々","explanationKo":"문맥상 「各々」가 가장 자연스럽다. 각각; 저마다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3145","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n多くの地域が技術革新の（　）を受けている。","options":["欧米","混合","恩恵","公表"],"answer":"恩恵","explanationKo":"문맥상 「恩恵」가 가장 자연스럽다. 은혜; 혜택; 도움을 받아 누리는 이익라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3146","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n目的を達成したため、調査委員会は（　）した。","options":["強化","解散","加速度","貨物"],"answer":"解散","explanationKo":"문맥상 「解散」가 가장 자연스럽다. 해산; 모임이나 조직을 없애거나 흩어짐라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3147","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新しい鉄道路線が来年（　）する予定だ。","options":["開通","侵入","区分","延長"],"answer":"開通","explanationKo":"문맥상 「開通」가 가장 자연스럽다. 개통; 도로나 철도·통신 등이 이용 가능해짐라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3148","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n装置の（　）速度を一定に保つ。","options":["循環","交流","空想","回転"],"answer":"回転","explanationKo":"문맥상 「回転」가 가장 자연스럽다. 회전; 축이나 중심을 기준으로 빙돎라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3149","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n試験終了後に模範（　）が公表された。","options":["作成","省略","解答","激増"],"answer":"解答","explanationKo":"문맥상 「解答」가 가장 자연스럽다. 해답; 문제를 풀어 낸 답라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3150","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n問い合わせには三営業日以内に（　）する。","options":["鑑賞","回答","順序","運河"],"answer":"回答","explanationKo":"문맥상 「回答」가 가장 자연스럽다. 회답; 질문이나 요구에 대한 답변라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3151","prompt":"「組織や物体の外側、または関係者以外。」という意味に最も近い語を選びなさい。","options":["外部","水平線","気圧","統一"],"answer":"外部","explanationKo":"「外部」의 핵심 의미는 외부; 조직이나 물체의 바깥쪽이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3152","prompt":"「閉じていた場所や施設を開き、自由に利用できるようにすること。」という意味に最も近い語を選びなさい。","options":["恩恵","雑音","勝敗","開放"],"answer":"開放","explanationKo":"「開放」의 핵심 의미는 개방; 문이나 시설 등을 열어 자유롭게 이용하게 함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3153","prompt":"「広大な海。また、海に関する領域。」という意味に最も近い語を選びなさい。","options":["下降","出勤","海洋","修繕"],"answer":"海洋","explanationKo":"「海洋」의 핵심 의미는 해양; 넓고 큰 바다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3154","prompt":"「実際には存在せず、想像によって作られたこと。」という意味に最も近い語を選びなさい。","options":["一流","架空","過剰","純情"],"answer":"架空","explanationKo":"「架空」의 핵심 의미는 가공; 실제로 존재하지 않고 상상으로 만든 것이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3155","prompt":"「一人一人。それぞれの人。」という意味に最も近い語を選びなさい。","options":["各自","一旦","始終","再三"],"answer":"各自","explanationKo":"「各自」의 핵심 의미는 각자; 각각의 사람이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','grammar',1,'〜に至るまで','{"pattern":"〜に至るまで","meaningKo":"〜에 이르기까지","explanation":"〜に至るまで는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"企画から運用に至るまで、全工程を記録した。","ko":"문맥에서 〜에 이르기까지의 의미로 쓰였다."},{"ja":"小さな部品に至るまで、安全基準を満たしているか確認した。","ko":"이 문장도 〜에 이르기까지의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','grammar',2,'〜にあっては','{"pattern":"〜にあっては","meaningKo":"〜의 경우에는; 〜에서는","explanation":"〜にあっては는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"緊急時にあっては、通常とは異なる判断が必要になる。","ko":"문맥에서 〜의 경우에는; 〜에서는의 의미로 쓰였다."},{"ja":"教育の現場にあっては、効率だけを優先すべきではない。","ko":"이 문장도 〜의 경우에는; 〜에서는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n企画から運用（　）、全工程を記録した。","options":["〜ては〜ては","〜に至るまで","〜はおろか","〜を契機に"],"answer":"〜に至るまで","explanationKo":"문맥상 〜에 이르기까지를 나타내는 「〜に至るまで」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n緊急時（　）、通常とは異なる判断が必要になる。","options":["〜にあっては","〜はさておき","〜を境に","〜てはじめて"],"answer":"〜にあっては","explanationKo":"문맥상 〜의 경우에는; 〜에서는를 나타내는 「〜にあっては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n細かな作業の正確さ（　）、この機械が最も優れている。","options":["〜ばかりに","〜を抜きにして","〜てはいられない","〜にかけては"],"answer":"〜にかけては","explanationKo":"문맥상 〜에 관한 한를 나타내는 「〜にかけては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2026-12-31','reading',1,'修理か更新かを選ぶ','{"passage":"古くなった設備への対応を判断することには、限られた資源を必要な箇所に配分できることという利点がある。もっとも、購入価格だけで決めると停止時間や保守負担を見落とすことには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、残りの使用期間と故障時の影響を含めて比較することが重要なのである。","questions":[{"prompt":"「修理か更新かを選ぶ」について筆者が最も重視していることは何か。","options":["残りの使用期間と故障時の影響を含めて比較すること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"残りの使用期間と故障時の影響を含めて比較すること","explanationKo":"본문에서는 残りの使用期間と故障時の影響を含めて比較すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["購入価格だけで決めると停止時間や保守負担を見落とすこと","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"購入価格だけで決めると停止時間や保守負担を見落とすこと","explanationKo":"주의할 점은 購入価格だけで決めると停止時間や保守負担を見落とすこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["限られた資源を必要な箇所に配分できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"限られた資源を必要な箇所に配分できること","explanationKo":"古くなった設備への対応を判断すること에는 限られた資源を必要な箇所に配分できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3161","prompt":"「工夫」の読み方として最も適切なものを選びなさい。","options":["けっさく","じゃくてん","ききん","くふう"],"answer":"くふう","explanationKo":"「工夫」는 「くふう」라고 읽는다. 뜻은 궁리; 좋은 방법을 찾아 여러모로 생각함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3162","prompt":"「敬語」の読み方として最も適切なものを選びなさい。","options":["こうたい","きゅうよう","けいご","おうせつ"],"answer":"けいご","explanationKo":"「敬語」는 「けいご」라고 읽는다. 뜻은 경어; 상대를 높이거나 공손함을 나타내는 말이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3163","prompt":"「警備」の読み方として最も適切なものを選びなさい。","options":["くぶん","けいび","がっかい","しんにゅう"],"answer":"けいび","explanationKo":"「警備」는 「けいび」라고 읽는다. 뜻은 경비; 사고나 범죄를 막기 위해 지킴이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3164","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの小説は作家の代表的な（　）として評価されている。","options":["傑作","原理","基盤","地盤"],"answer":"傑作","explanationKo":"문맥상 「傑作」가 가장 자연스럽다. 걸작; 매우 뛰어난 작품라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3165","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n人を傷つける（　）な冗談は慎むべきだ。","options":["厳重","不規則","格別","下品"],"answer":"下品","explanationKo":"문맥상 「下品」가 가장 자연스럽다. 상스럽다; 품위가 없음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3166","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新入社員は一か月間の（　）を受ける。","options":["過失","期限","研修","概論"],"answer":"研修","explanationKo":"문맥상 「研修」가 가장 자연스럽다. 연수; 업무에 필요한 지식과 기술을 배우는 과정라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3167","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n個人の努力だけで対応するには（　）がある。","options":["気圧","限度","私立","水平線"],"answer":"限度","explanationKo":"문맥상 「限度」가 가장 자연스럽다. 한도; 허용하거나 가능한 범위의 끝라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3168","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）価格の上昇が製品価格に反映された。","options":["原料","活字","催促","課税"],"answer":"原料","explanationKo":"문맥상 「原料」가 가장 자연스럽다. 원료; 제품을 만드는 데 바탕이 되는 재료라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3169","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n十分な合意のないまま（　）に計画を進めた。","options":["高度","案外","安易","強引"],"answer":"強引","explanationKo":"문맥상 「強引」가 가장 자연스럽다. 강압적; 무리하게 일을 밀어붙이는 모양라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3170","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な素材を使えば必ず良い製品になるとは限らない。","options":["不規則","下品","高級","厳重"],"answer":"高級","explanationKo":"문맥상 「高級」가 가장 자연스럽다. 고급; 품질이나 등급이 높음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3171","prompt":"「実用性と美しさを備えた品物を作る技術。」という意味に最も近い語を選びなさい。","options":["過程","工芸","応援","観念"],"answer":"工芸","explanationKo":"「工芸」의 핵심 의미는 공예; 실용성과 아름다움을 갖춘 물건을 만드는 기술이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3172","prompt":"「二つ以上の線や動きが互いに交わること。」という意味に最も近い語を選びなさい。","options":["交差","肯定","開通","集合"],"answer":"交差","explanationKo":"「交差」의 핵심 의미는 교차; 서로 엇갈려 지나거나 만남이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3173","prompt":"「講義や指導を担当する人。」という意味に最も近い語を選びなさい。","options":["重役","液体","産地","講師"],"answer":"講師","explanationKo":"「講師」의 핵심 의미는 강사; 강의나 지도를 담당하는 사람이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3174","prompt":"「社会を構成する不特定多数の人々。」という意味に最も近い語を選びなさい。","options":["商業","苦情","公衆","国立"],"answer":"公衆","explanationKo":"「公衆」의 핵심 의미는 공중; 사회를 이루는 일반 대중이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3175","prompt":"「建物の高い階層、または高くそびえること。」という意味に最も近い語を選びなさい。","options":["光線","高層","給与","会館"],"answer":"高層","explanationKo":"「高層」의 핵심 의미는 고층; 건물의 높은 층이나 높이 솟은 구조이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','grammar',1,'〜にかけては','{"pattern":"〜にかけては","meaningKo":"〜에 관한 한","explanation":"〜にかけては는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"データの分析にかけては、彼の右に出る者はいない。","ko":"문맥에서 〜에 관한 한의 의미로 쓰였다."},{"ja":"細かな作業の正確さにかけては、この機械が最も優れている。","ko":"이 문장도 〜에 관한 한의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','grammar',2,'〜にせよ〜にせよ','{"pattern":"〜にせよ〜にせよ","meaningKo":"〜이든 〜이든","explanation":"〜にせよ〜にせよ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"採用するにせよ見送るにせよ、理由を明確に説明すべきだ。","ko":"문맥에서 〜이든 〜이든의 의미로 쓰였다."},{"ja":"賛成するにせよ反対するにせよ、資料を読んでから判断してほしい。","ko":"이 문장도 〜이든 〜이든의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nデータの分析（　）、彼の右に出る者はいない。","options":["〜にかけては","〜ばかりに","〜を抜きにして","〜てはいられない"],"answer":"〜にかけては","explanationKo":"문맥상 〜에 관한 한를 나타내는 「〜にかけては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）、理由を明確に説明すべきだ。","options":["〜べくして","〜からして","〜てばかりはいられない","〜にせよ〜にせよ"],"answer":"〜にせよ〜にせよ","explanationKo":"문맥상 〜이든 〜이든를 나타내는 「〜にせよ〜にせよ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n記録を残さない対応は、同じ失敗を容認する（　）。","options":["〜くらいなら","〜ところを","〜にひとしい","〜までだ"],"answer":"〜にひとしい","explanationKo":"문맥상 〜나 다름없다를 나타내는 「〜にひとしい」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-01','reading',1,'説明会を決定前に開く','{"passage":"公共計画について住民に説明することには、生活への影響と地域固有の事情を把握できることという利点がある。もっとも、決定後に形式的に聞くだけでは意見を反映できないことには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、変更可能な段階と範囲を示して意見を求めることが重要なのである。","questions":[{"prompt":"「説明会を決定前に開く」について筆者が最も重視していることは何か。","options":["変更可能な段階と範囲を示して意見を求めること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"変更可能な段階と範囲を示して意見を求めること","explanationKo":"본문에서는 変更可能な段階と範囲を示して意見を求めること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["決定後に形式的に聞くだけでは意見を反映できないこと","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"決定後に形式的に聞くだけでは意見を反映できないこと","explanationKo":"주의할 점은 決定後に形式的に聞くだけでは意見を反映できないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["生活への影響と地域固有の事情を把握できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"生活への影響と地域固有の事情を把握できること","explanationKo":"公共計画について住民に説明すること에는 生活への影響と地域固有の事情を把握できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3181","prompt":"「国立」の読み方として最も適切なものを選びなさい。","options":["こくりつ","かんちょう","こたい","げいのう"],"answer":"こくりつ","explanationKo":"「国立」는 「こくりつ」라고 읽는다. 뜻은 국립; 국가가 설립하고 운영함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3182","prompt":"「娯楽」の読み方として最も適切なものを選びなさい。","options":["いんりょく","けっさく","しゅうかい","ごらく"],"answer":"ごらく","explanationKo":"「娯楽」는 「ごらく」라고 읽는다. 뜻은 오락; 즐거움을 얻기 위한 활동이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3183","prompt":"「混合」の読み方として最も適切なものを選びなさい。","options":["かんかく","こうもく","こんごう","めんぜい"],"answer":"こんごう","explanationKo":"「混合」는 「こんごう」라고 읽는다. 뜻은 혼합; 서로 다른 것을 섞음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3184","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n公平な基準に基づいて答案を（　）した。","options":["恩恵","採点","公式","社会科学"],"answer":"採点","explanationKo":"문맥상 「採点」가 가장 자연스럽다. 채점; 답안을 평가하여 점수를 매김라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3185","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n施設内での（　）には事前の許可が必要だ。","options":["撮影","演劇","合同","主役"],"answer":"撮影","explanationKo":"문맥상 「撮影」가 가장 자연스럽다. 촬영; 사진이나 영상을 찍음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3186","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）が多く、通話の内容を聞き取れなかった。","options":["自治","解答","実習","雑音"],"answer":"雑音","explanationKo":"문맥상 「雑音」가 가장 자연스럽다. 잡음; 필요하지 않은 소리나 신호라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3187","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n提案が承認されたので、（　）準備に取りかかった。","options":["幾分","一段","早速","一応"],"answer":"早速","explanationKo":"문맥상 「早速」가 가장 자연스럽다. 즉시; 지체하지 않고 바로라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3188","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）によって品質や風味に違いがある。","options":["原始","産地","対策","過半数"],"answer":"産地","explanationKo":"문맥상 「産地」가 가장 자연스럽다. 산지; 어떤 생산물이 주로 생산되는 지역라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3189","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n工場の（　）内では安全規則を守らなければならない。","options":["敷地","形式","重役","液体"],"answer":"敷地","explanationKo":"문맥상 「敷地」가 가장 자연스럽다. 부지; 건물이나 시설이 들어선 토지라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3190","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n不具合の原因を（　）調査してください。","options":["各々","幾分","比較的","至急"],"answer":"至急","explanationKo":"문맥상 「至急」가 가장 자연스럽다. 지급; 매우 급함; 최대한 빨리라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3191","prompt":"「必要な物を自分で持って行くこと。」という意味に最も近い語を選びなさい。","options":["教養","紙幣","持参","功績"],"answer":"持参","explanationKo":"「持参」의 핵심 의미는 지참; 직접 가지고 감이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3192","prompt":"「初めから終わりまで。また、絶えず。」という意味に最も近い語を選びなさい。","options":["一斉","始終","比較的","以後"],"answer":"始終","explanationKo":"「始終」의 핵심 의미는 시종; 처음부터 끝까지; 늘이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3193","prompt":"「体の構え。また、物事に取り組む態度。」という意味に最も近い語を選びなさい。","options":["姿勢","免税","激増","応接"],"answer":"姿勢","explanationKo":"「姿勢」의 핵심 의미는 자세; 몸가짐; 어떤 일에 임하는 태도이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3194","prompt":"「子や孫など、後の世代に続く血縁者。」という意味に最も近い語を選びなさい。","options":["消耗","警備","感激","子孫"],"answer":"子孫","explanationKo":"「子孫」의 핵심 의미는 자손; 후대에 이어지는 자녀와 그 후손이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3195","prompt":"「実際の作業を行いながら知識や技能を学ぶこと。」という意味に最も近い語を選びなさい。","options":["作者","可決","実習","角度"],"answer":"実習","explanationKo":"「実習」의 핵심 의미는 실습; 실제 작업을 통해 기술을 익힘이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','grammar',1,'〜にひとしい','{"pattern":"〜にひとしい","meaningKo":"〜나 다름없다","explanation":"〜にひとしい는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"確認をせずに公開するのは、誤情報を広めるにひとしい。","ko":"문맥에서 〜나 다름없다의 의미로 쓰였다."},{"ja":"記録を残さない対応は、同じ失敗を容認するにひとしい。","ko":"이 문장도 〜나 다름없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','grammar',2,'〜はおろか','{"pattern":"〜はおろか","meaningKo":"〜은커녕","explanation":"〜はおろか는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"原因の説明はおろか、謝罪さえなかった。","ko":"문맥에서 〜은커녕의 의미로 쓰였다."},{"ja":"専門知識はおろか、基本的な手順も理解していない。","ko":"이 문장도 〜은커녕의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n確認をせずに公開するのは、誤情報を広める（　）。","options":["〜までだ","〜くらいなら","〜ところを","〜にひとしい"],"answer":"〜にひとしい","explanationKo":"문맥상 〜나 다름없다를 나타내는 「〜にひとしい」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n原因の説明（　）、謝罪さえなかった。","options":["〜ずとも","〜とはいえ","〜はおろか","〜までのことだ"],"answer":"〜はおろか","explanationKo":"문맥상 〜은커녕를 나타내는 「〜はおろか」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n細かな表現（　）、提案の方向性には賛成だ。","options":["〜とはいうものの","〜はさておき","〜を契機に","〜たりとも〜ない"],"answer":"〜はさておき","explanationKo":"문맥상 〜은 제쳐 두고를 나타내는 「〜はさておき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-02','reading',1,'暫定判断を更新する','{"passage":"情報が不十分な段階で一時的に決めることには、対応の遅れによる被害を抑えられることという利点がある。もっとも、暫定という表示だけでは判断が固定化することには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、再検討の時期と判断を変える条件を先に定めることが重要なのである。","questions":[{"prompt":"「暫定判断を更新する」について筆者が最も重視していることは何か。","options":["再検討の時期と判断を変える条件を先に定めること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"再検討の時期と判断を変える条件を先に定めること","explanationKo":"본문에서는 再検討の時期と判断を変える条件を先に定めること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["暫定という表示だけでは判断が固定化すること","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"暫定という表示だけでは判断が固定化すること","explanationKo":"주의할 점은 暫定という表示だけでは判断が固定化すること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["対応の遅れによる被害を抑えられること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"対応の遅れによる被害を抑えられること","explanationKo":"情報が不十分な段階で一時的に決めること에는 対応の遅れによる被害を抑えられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3201","prompt":"「集合」の読み方として最も適切なものを選びなさい。","options":["ごうどう","しゅうごう","じゅんじょ","えんげき"],"answer":"しゅうごう","explanationKo":"「集合」는 「しゅうごう」라고 읽는다. 뜻은 집합; 한곳에 모임; 수학에서 일정 조건을 만족하는 대상의 모임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3202","prompt":"「重体」の読み方として最も適切なものを選びなさい。","options":["じゅうたい","かいせつ","じち","かいとう"],"answer":"じゅうたい","explanationKo":"「重体」는 「じゅうたい」라고 읽는다. 뜻은 중태; 병이나 부상이 매우 심각한 상태이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3203","prompt":"「終了」の読み方として最も適切なものを選びなさい。","options":["きぐ","のうさんぶつ","きょくせん","しゅうりょう"],"answer":"しゅうりょう","explanationKo":"「終了」는 「しゅうりょう」라고 읽는다. 뜻은 종료; 일이나 행사가 끝남이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3204","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n荷物の（　）が制限を超えていないか確認した。","options":["対策","過半数","重量","空想"],"answer":"重量","explanationKo":"문맥상 「重量」가 가장 자연스럽다. 중량; 물체의 무게라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3205","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n漢字単体だけでなく（　）の読み方も覚える。","options":["重役","熟語","効力","形式"],"answer":"熟語","explanationKo":"문맥상 「熟語」가 가장 자연스럽다. 숙어; 두 글자 이상의 한자 결합이나 관용적인 어구라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3206","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大雪のため（　）時刻を遅らせることになった。","options":["出勤","交流","苦心","対策"],"answer":"出勤","explanationKo":"문맥상 「出勤」가 가장 자연스럽다. 출근; 근무처에 나감라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3207","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n来週は取引先との打ち合わせで大阪へ（　）する。","options":["性質","功績","教養","出張"],"answer":"出張","explanationKo":"문맥상 「出張」가 가장 자연스럽다. 출장; 업무 때문에 다른 지역으로 감라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3208","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n適切な保守によって設備の（　）を延ばせる。","options":["緯度","空中","寿命","記号"],"answer":"寿命","explanationKo":"문맥상 「寿命」가 가장 자연스럽다. 수명; 생물이 살아 있는 기간; 기계가 사용 가능한 기간라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3209","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n地域の再生では住民自身が（　）になるべきだ。","options":["激増","主役","気体","免税"],"answer":"主役","explanationKo":"문맥상 「主役」가 가장 자연스럽다. 주역; 작품의 중심 역할; 일의 중심 인물라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3210","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な若者の成長を描いた物語だ。","options":["純情","下品","案外","純粋"],"answer":"純情","explanationKo":"문맥상 「純情」가 가장 자연스럽다. 순정; 순수하고 꾸밈없는 마음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3211","prompt":"「商品やサービスを売買して利益を得る事業。」という意味に最も近い語を選びなさい。","options":["活躍","出張","休息","商業"],"answer":"商業","explanationKo":"「商業」의 핵심 의미는 상업; 상품이나 서비스를 거래하여 이익을 얻는 활동이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3212","prompt":"「国内外の商品取引を仲介する会社。」という意味に最も近い語を選びなさい。","options":["意義","官庁","商社","加熱"],"answer":"商社","explanationKo":"「商社」의 핵심 의미는 상사; 국내외 상품 거래를 중개하는 회사이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3213","prompt":"「病原性のある微生物を除去したり弱めたりすること。」という意味に最も近い語を選びなさい。","options":["出張","消毒","自衛","活躍"],"answer":"消毒","explanationKo":"「消毒」의 핵심 의미는 소독; 병원성 미생물을 없애거나 약화함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3214","prompt":"「勝つことと負けること。」という意味に最も近い語を選びなさい。","options":["勝敗","社会科学","海洋","子孫"],"answer":"勝敗","explanationKo":"「勝敗」의 핵심 의미는 승패; 이김과 짐이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3215","prompt":"「液体が気体に変わること。また、人が突然姿を消すこと。」という意味に最も近い語を選びなさい。","options":["観念","学術","公式","蒸発"],"answer":"蒸発","explanationKo":"「蒸発」의 핵심 의미는 증발; 액체가 기체로 변함; 사람이 자취를 감춤이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','grammar',1,'〜はさておき','{"pattern":"〜はさておき","meaningKo":"〜은 제쳐 두고","explanation":"〜はさておき는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"費用の問題はさておき、まず安全性を確認しよう。","ko":"문맥에서 〜은 제쳐 두고의 의미로 쓰였다."},{"ja":"細かな表現はさておき、提案の方向性には賛成だ。","ko":"이 문장도 〜은 제쳐 두고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','grammar',2,'〜ばかりに','{"pattern":"〜ばかりに","meaningKo":"단지 〜한 탓에","explanation":"〜ばかりに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"確認を怠ったばかりに、重大な誤りを見逃した。","ko":"문맥에서 단지 〜한 탓에의 의미로 쓰였다."},{"ja":"不用意な発言をしたばかりに、信頼を失ってしまった。","ko":"이 문장도 단지 〜한 탓에의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n費用の問題（　）、まず安全性を確認しよう。","options":["〜たりとも〜ない","〜とはいうものの","〜はさておき","〜を契機に"],"answer":"〜はさておき","explanationKo":"문맥상 〜은 제쳐 두고를 나타내는 「〜はさておき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n確認を怠った（　）、重大な誤りを見逃した。","options":["〜とまではいかないが","〜ばかりに","〜を境に","〜だろうが〜だろうが"],"answer":"〜ばかりに","explanationKo":"문맥상 단지 〜한 탓에를 나타내는 「〜ばかりに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n利用者の声を無視した制度は、見直される（　）見直された。","options":["〜べくして","〜を抜きにして","〜ては〜ては","〜に至る"],"answer":"〜べくして","explanationKo":"문맥상 당연히 〜하게 되어를 나타내는 「〜べくして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-03','reading',1,'手順書に残らない知識','{"passage":"熟練者の作業を文書化することには、担当者が変わっても基本的な作業を再現できることという利点がある。もっとも、判断の理由や感覚的な兆候は手順だけでは伝わりにくいことには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、具体的な事例と判断過程を共同作業で引き継ぐことが重要なのである。","questions":[{"prompt":"「手順書に残らない知識」について筆者が最も重視していることは何か。","options":["具体的な事例と判断過程を共同作業で引き継ぐこと","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"具体的な事例と判断過程を共同作業で引き継ぐこと","explanationKo":"본문에서는 具体的な事例と判断過程を共同作業で引き継ぐこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["判断の理由や感覚的な兆候は手順だけでは伝わりにくいこと","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"判断の理由や感覚的な兆候は手順だけでは伝わりにくいこと","explanationKo":"주의할 점은 判断の理由や感覚的な兆候は手順だけでは伝わりにくいこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["担当者が変わっても基本的な作業を再現できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"担当者が変わっても基本的な作業を再現できること","explanationKo":"熟練者の作業を文書化すること에는 担当者が変わっても基本的な作業を再現できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3221","prompt":"「感激」の読み方として最も適切なものを選びなさい。","options":["けいぞく","おうせつ","かんげき","せいさく"],"answer":"かんげき","explanationKo":"「感激」는 「かんげき」라고 읽는다. 뜻은 감격; 마음이 크게 움직여 깊이 감동함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3222","prompt":"「乾燥」の読み方として最も適切なものを選びなさい。","options":["くしん","かんそう","しょうもう","こうりゅう"],"answer":"かんそう","explanationKo":"「乾燥」는 「かんそう」라고 읽는다. 뜻은 건조; 수분이 없어 마름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3223","prompt":"「感想」の読み方として最も適切なものを選びなさい。","options":["かんそう","さいなん","こうし","じゅうりょう"],"answer":"かんそう","explanationKo":"「感想」는 「かんそう」라고 읽는다. 뜻은 감상; 보고 듣거나 경험한 뒤 느낀 생각이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3224","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長期の干ばつが深刻な（　）を引き起こした。","options":["集会","記号","緯度","飢饉"],"answer":"飢饉","explanationKo":"문맥상 「飢饉」가 가장 자연스럽다. 기근; 식량이 심각하게 부족해 굶주리는 상태라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3225","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n実験に使う（　）を事前に点検した。","options":["気体","免税","器具","大学院"],"answer":"器具","explanationKo":"문맥상 「器具」가 가장 자연스럽다. 기구; 특정 작업에 사용하는 도구라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3226","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n地図上の（　）が何を示すか確認した。","options":["消耗","記号","侵入","仮定"],"answer":"記号","explanationKo":"문맥상 「記号」가 가장 자연스럽다. 기호; 일정한 의미를 나타내는 표시라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3227","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n伝統的な（　）が地域の人々によって受け継がれている。","options":["儀式","就任","活躍","出張"],"answer":"儀式","explanationKo":"문맥상 「儀式」가 가장 자연스럽다. 의식; 정해진 절차에 따라 치르는 행사라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3228","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n南極の観測（　）で気象データを収集する。","options":["集合","加熱","意義","基地"],"answer":"基地","explanationKo":"문맥상 「基地」가 가장 자연스럽다. 기지; 군사·관측·활동 등의 거점라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3229","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n設備点検のため工場は一週間（　）する。","options":["自衛","活躍","休業","移転"],"answer":"休業","explanationKo":"문맥상 「休業」가 가장 자연스럽다. 휴업; 영업이나 업무를 일시적으로 쉼라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3230","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n経験や能力を（　）に適切に反映させる。","options":["海洋","給与","公共","社会科学"],"answer":"給与","explanationKo":"문맥상 「給与」가 가장 자연스럽다. 급여; 근로의 대가로 지급되는 돈라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3231","prompt":"「仕事などを休み、心身を回復させること。」という意味に最も近い語を選びなさい。","options":["休養","開会","観念","学術"],"answer":"休養","explanationKo":"「休養」의 핵심 의미는 휴양; 몸과 마음을 쉬게 해 회복함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3232","prompt":"「一定の時期や手順に従って行われる催し。」という意味に最も近い語を選びなさい。","options":["商業","青少年","学部","行事"],"answer":"行事","explanationKo":"「行事」의 핵심 의미는 행사; 일정한 때와 절차에 따라 치르는 일이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3233","prompt":"「相手の厚意や迷惑をかけることに対して、申し訳なく思うこと。」という意味に最も近い語を選びなさい。","options":["一流","曖昧","恐縮","強引"],"answer":"恐縮","explanationKo":"「恐縮」의 핵심 의미는 송구; 고마움이나 미안함 때문에 몸 둘 바를 모름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3234","prompt":"「魚介類を捕獲したり養殖したりする産業。」という意味に最も近い語を選びなさい。","options":["解散","漁業","圧縮","削除"],"answer":"漁業","explanationKo":"「漁業」의 핵심 의미는 어업; 물고기나 해산물을 잡거나 기르는 산업이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3235","prompt":"「現実にはないことを自由に思い描くこと。」という意味に最も近い語を選びなさい。","options":["空想","私立","水平線","気圧"],"answer":"空想","explanationKo":"「空想」의 핵심 의미는 공상; 현실과 떨어진 일을 자유롭게 상상함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','grammar',1,'〜べくして','{"pattern":"〜べくして","meaningKo":"당연히 〜하게 되어","explanation":"〜べくして는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"十分な備えがなければ、事故は起こるべくして起こる。","ko":"문맥에서 당연히 〜하게 되어의 의미로 쓰였다."},{"ja":"利用者の声を無視した制度は、見直されるべくして見直された。","ko":"이 문장도 당연히 〜하게 되어의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','grammar',2,'〜までだ','{"pattern":"〜までだ","meaningKo":"그저 〜할 뿐이다","explanation":"〜までだ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"交渉がまとまらなければ、別の方法を探すまでだ。","ko":"문맥에서 그저 〜할 뿐이다의 의미로 쓰였다."},{"ja":"事実が確認できないなら、公表を延期するまでだ。","ko":"이 문장도 그저 〜할 뿐이다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n十分な備えがなければ、事故は起こる（　）起こる。","options":["〜に至る","〜べくして","〜を抜きにして","〜ては〜ては"],"answer":"〜べくして","explanationKo":"문맥상 당연히 〜하게 되어를 나타내는 「〜べくして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n交渉がまとまらなければ、別の方法を探す（　）。","options":["〜までだ","〜からして","〜てはじめて","〜に至るまで"],"answer":"〜までだ","explanationKo":"문맥상 그저 〜할 뿐이다를 나타내는 「〜までだ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n条件が合わなければ、参加を見送る（　）。","options":["〜くらいなら","〜てはいられない","〜にあっては","〜までのことだ"],"answer":"〜までのことだ","explanationKo":"문맥상 그저 〜하면 될 일이다를 나타내는 「〜までのことだ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-04','reading',1,'まれな危険に備える','{"passage":"発生頻度の低い事故への対策を考えることには、重大な被害を避ける選択肢を事前に持てることという利点がある。もっとも、可能性を列挙するだけでは費用が際限なく増えることには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、被害の大きさと代替手段の有無から優先度を決めることが重要なのである。","questions":[{"prompt":"「まれな危険に備える」について筆者が最も重視していることは何か。","options":["被害の大きさと代替手段の有無から優先度を決めること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"被害の大きさと代替手段の有無から優先度を決めること","explanationKo":"본문에서는 被害の大きさと代替手段の有無から優先度を決めること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["可能性を列挙するだけでは費用が際限なく増えること","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"可能性を列挙するだけでは費用が際限なく増えること","explanationKo":"주의할 점은 可能性を列挙するだけでは費用が際限なく増えること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["重大な被害を避ける選択肢を事前に持てること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"重大な被害を避ける選択肢を事前に持てること","explanationKo":"発生頻度の低い事故への対策を考えること에는 重大な被害を避ける選択肢を事前に持てること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3241","prompt":"「酸性」の読み方として最も適切なものを選びなさい。","options":["しりつ","だいがくいん","きたい","さんせい"],"answer":"さんせい","explanationKo":"「酸性」는 「さんせい」라고 읽는다. 뜻은 산성; 산의 성질을 띠는 상태이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3242","prompt":"「中性」の読み方として最も適切なものを選びなさい。","options":["しんにゅう","しょうもう","ちゅうせい","かてい"],"answer":"ちゅうせい","explanationKo":"「中性」는 「ちゅうせい」라고 읽는다. 뜻은 중성; 산성도 알칼리성도 아닌 상태; 어느 쪽에도 치우치지 않음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3243","prompt":"「性別」の読み方として最も適切なものを選びなさい。","options":["かつやく","せいべつ","かくちょう","しゅうにん"],"answer":"せいべつ","explanationKo":"「性別」는 「せいべつ」라고 읽는다. 뜻은 성별; 성에 따른 구분이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3244","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n地域全体で若い起業家を（　）する取り組みが始まった。","options":["応援","給与","会館","光線"],"answer":"応援","explanationKo":"문맥상 「応援」가 가장 자연스럽다. 응원; 힘을 북돋우거나 도움을 줌라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3245","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n技術革新が（　）を増して進んでいる。","options":["育児","抽象","為替","加速度"],"answer":"加速度","explanationKo":"문맥상 「加速度」가 가장 자연스럽다. 가속도; 단위 시간당 속도의 변화량라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3246","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の向こうから太陽が昇った。","options":["公共","社会科学","水平線","有無"],"answer":"水平線","explanationKo":"문맥상 「水平線」가 가장 자연스럽다. 수평선; 바다와 하늘이 맞닿아 보이는 선라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3247","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）で環境政策について研究している。","options":["産地","大学院","順序","演劇"],"answer":"大学院","explanationKo":"문맥상 「大学院」가 가장 자연스럽다. 대학원; 대학 졸업 후 전문 연구를 하는 교육기관라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3248","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n工場周辺の（　）に汚染がないか調査した。","options":["地下水","国立","商業","苦情"],"answer":"地下水","explanationKo":"문맥상 「地下水」가 가장 자연스럽다. 지하수; 땅속에 스며들어 존재하는 물라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3249","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n地元の（　）を使った商品を開発した。","options":["給与","回数","耕地","農産物"],"answer":"農産物","explanationKo":"문맥상 「農産物」가 가장 자연스럽다. 농산물; 농업을 통해 생산한 물품라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3250","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n仕事と（　）を両立できる制度が求められている。","options":["限度","集会","育児","実力"],"answer":"育児","explanationKo":"문맥상 「育児」가 가장 자연스럽다. 육아; 어린아이를 돌보고 기름라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3251","prompt":"「赤道を基準にした南北方向の位置。」という意味に最も近い語を選びなさい。","options":["交流","緯度","謙遜","応対"],"answer":"緯度","explanationKo":"「緯度」의 핵심 의미는 위도; 적도를 기준으로 한 남북 방향의 위치이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3252","prompt":"「野菜、果樹、草花などを栽培すること。」という意味に最も近い語を選びなさい。","options":["園芸","研修","乾燥","公務"],"answer":"園芸","explanationKo":"「園芸」의 핵심 의미는 원예; 채소·과일·화초 등을 재배하는 일이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3253","prompt":"「熱帯と寒帯の間にある気候帯。」という意味に最も近い語を選びなさい。","options":["概論","公害","境界","温帯"],"answer":"温帯","explanationKo":"「温帯」의 핵심 의미는 온대; 열대와 한대 사이의 기후대이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3254","prompt":"「会議や催しを始めること。」という意味に最も近い語を選びなさい。","options":["研修","乾燥","開会","就任"],"answer":"開会","explanationKo":"「開会」의 핵심 의미는 개회; 회의나 행사를 시작함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3255","prompt":"「集会や催しなどに使用する建物。」という意味に最も近い語を選びなさい。","options":["集会","会館","学力","限度"],"answer":"会館","explanationKo":"「会館」의 핵심 의미는 회관; 집회나 행사에 사용하는 건물이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','grammar',1,'〜までのことだ','{"pattern":"〜までのことだ","meaningKo":"그저 〜하면 될 일이다","explanation":"〜までのことだ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"今回失敗したなら、原因を直してもう一度試すまでのことだ。","ko":"문맥에서 그저 〜하면 될 일이다의 의미로 쓰였다."},{"ja":"条件が合わなければ、参加を見送るまでのことだ。","ko":"이 문장도 그저 〜하면 될 일이다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','grammar',2,'〜を契機に','{"pattern":"〜を契機に","meaningKo":"〜을 계기로","explanation":"〜を契機に는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"制度改正を契機に、業務手順を全面的に見直した。","ko":"문맥에서 〜을 계기로의 의미로 쓰였다."},{"ja":"事故を契機に、安全教育が強化された。","ko":"이 문장도 〜을 계기로의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n今回失敗したなら、原因を直してもう一度試す（　）。","options":["〜までのことだ","〜くらいなら","〜てはいられない","〜にあっては"],"answer":"〜までのことだ","explanationKo":"문맥상 그저 〜하면 될 일이다를 나타내는 「〜までのことだ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n制度改正（　）、業務手順を全面的に見直した。","options":["〜ずとも","〜てばかりはいられない","〜にかけては","〜を契機に"],"answer":"〜を契機に","explanationKo":"문맥상 〜을 계기로를 나타내는 「〜を契機に」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n駅前の再開発（　）、地域の人口が増え始めた。","options":["〜ところを","〜にせよ〜にせよ","〜を境に","〜たりとも〜ない"],"answer":"〜を境に","explanationKo":"문맥상 〜을 경계로; 〜을 기점으로를 나타내는 「〜を境に」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-05','reading',1,'回答しなかった人を考える','{"passage":"アンケートの結果から意見を分析することには、回答者が感じている問題や傾向を把握できることという利点がある。もっとも、回答しやすい人だけの結果を全体に当てはめると偏ることには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、未回答者の特徴と回答方法による差を検討することが重要なのである。","questions":[{"prompt":"「回答しなかった人を考える」について筆者が最も重視していることは何か。","options":["未回答者の特徴と回答方法による差を検討すること","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"未回答者の特徴と回答方法による差を検討すること","explanationKo":"본문에서는 未回答者の特徴と回答方法による差を検討すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["回答しやすい人だけの結果を全体に当てはめると偏ること","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"回答しやすい人だけの結果を全体に当てはめると偏ること","explanationKo":"주의할 점은 回答しやすい人だけの結果を全体に当てはめると偏ること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["回答者が感じている問題や傾向を把握できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"回答者が感じている問題や傾向を把握できること","explanationKo":"アンケートの結果から意見を分析すること에는 回答者が感じている問題や傾向を把握できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3261","prompt":"「加速」の読み方として最も適切なものを選びなさい。","options":["かそく","いど","くうちゅう","いてん"],"answer":"かそく","explanationKo":"「加速」는 「かそく」라고 읽는다. 뜻은 가속; 속도를 더 빠르게 함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3262","prompt":"「学会」の読み方として最も適切なものを選びなさい。","options":["たいせい","うむ","こうきょう","がっかい"],"answer":"がっかい","explanationKo":"「学会」는 「がっかい」라고 읽는다. 뜻은 학회; 연구자들이 연구 발표와 교류를 하는 단체나 모임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3263","prompt":"「活字」の読み方として最も適切なものを選びなさい。","options":["じゅんじょ","えんげき","かつじ","けはい"],"answer":"かつじ","explanationKo":"「活字」는 「かつじ」라고 읽는다. 뜻은 활자; 인쇄에 쓰는 글자; 인쇄된 문자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3264","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n所定の（　）を修了すると資格を取得できる。","options":["商業","課程","売上","国立"],"answer":"課程","explanationKo":"문맥상 「課程」가 가장 자연스럽다. 과정; 교육기관에서 정한 학습 단계와 내용라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3265","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n食品は中心まで十分に（　）してください。","options":["加熱","合理","区域","社説"],"answer":"加熱","explanationKo":"문맥상 「加熱」가 가장 자연스럽다. 가열; 열을 가해 온도를 높임라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3266","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n鉄道による（　）輸送の需要が高まっている。","options":["緯度","原産","圧縮","貨物"],"answer":"貨物","explanationKo":"문맥상 「貨物」가 가장 자연스럽다. 화물; 운송하는 짐이나 상품라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3267","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n感染対策として定期的に（　）を行う。","options":["実物","私立","換気","各地"],"answer":"換気","explanationKo":"문맥상 「換気」가 가장 자연스럽다. 환기; 실내 공기를 바깥 공기와 바꿈라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3268","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の低下に伴って天候が崩れた。","options":["乾燥","気圧","省略","研修"],"answer":"気圧","explanationKo":"문맥상 「気圧」가 가장 자연스럽다. 기압; 공기가 누르는 압력라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3269","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n液体が蒸発すると（　）に変化する。","options":["気体","消毒","概論","公害"],"answer":"気体","explanationKo":"문맥상 「気体」가 가장 자연스럽다. 기체; 일정한 모양과 부피가 없는 물질 상태라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3270","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n台風の接近により午後の授業は（　）となった。","options":["拡充","就任","研修","休講"],"answer":"休講","explanationKo":"문맥상 「休講」가 가장 자연스럽다. 휴강; 예정된 강의를 쉼라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3271","prompt":"「活動を止めて、心身を休めること。」という意味に最も近い語を選びなさい。","options":["消毒","規律","休息","鑑賞"],"answer":"休息","explanationKo":"「休息」의 핵심 의미는 휴식; 하던 일을 멈추고 몸과 마음을 쉼이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3272","prompt":"「人や物が列を作って並ぶこと。また、数学のマトリックス。」という意味に最も近い語を選びなさい。","options":["私立","行列","各地","実物"],"answer":"行列","explanationKo":"「行列」의 핵심 의미는 행렬; 줄을 지어 늘어선 사람이나 것; 수학의 행렬이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3273","prompt":"「まっすぐではなく、滑らかに曲がった線。」という意味に最も近い語を選びなさい。","options":["曲線","正面","中性","活字"],"answer":"曲線","explanationKo":"「曲線」의 핵심 의미는 곡선; 굽어 있는 선이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3274","prompt":"「地面から離れた空間。」という意味に最も近い語を選びなさい。","options":["学部","評論","拡張","空中"],"answer":"空中","explanationKo":"「空中」의 핵심 의미는 공중; 땅에서 떨어진 공간이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3275","prompt":"「動植物や生産物が最初に生じた土地。」という意味に最も近い語を選びなさい。","options":["執筆","回答","原産","改造"],"answer":"原産","explanationKo":"「原産」의 핵심 의미는 원산; 동식물이나 생산물의 최초 산지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','grammar',1,'〜を境に','{"pattern":"〜を境に","meaningKo":"〜을 경계로; 〜을 기점으로","explanation":"〜を境に는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"その発表を境に、世論の流れが大きく変わった。","ko":"문맥에서 〜을 경계로; 〜을 기점으로의 의미로 쓰였다."},{"ja":"駅前の再開発を境に、地域の人口が増え始めた。","ko":"이 문장도 〜을 경계로; 〜을 기점으로의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','grammar',2,'〜を抜きにして','{"pattern":"〜を抜きにして","meaningKo":"〜을 빼고는; 〜없이","explanation":"〜を抜きにして는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"現場の意見を抜きにして、実効性のある制度は作れない。","ko":"문맥에서 〜을 빼고는; 〜없이의 의미로 쓰였다."},{"ja":"安全性の検証を抜きにして、導入を決めることはできない。","ko":"이 문장도 〜을 빼고는; 〜없이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその発表（　）、世論の流れが大きく変わった。","options":["〜たりとも〜ない","〜ところを","〜にせよ〜にせよ","〜を境に"],"answer":"〜を境に","explanationKo":"문맥상 〜을 경계로; 〜을 기점으로를 나타내는 「〜を境に」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n現場の意見（　）、実効性のある制度は作れない。","options":["〜とはいえ","〜にひとしい","〜を抜きにして","〜だろうが〜だろうが"],"answer":"〜を抜きにして","explanationKo":"문맥상 〜을 빼고는; 〜없이를 나타내는 「〜を抜きにして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n責任者の態度（　）、事態の深刻さがうかがえる。","options":["〜はおろか","〜からして","〜ては〜ては","〜とはいうものの"],"answer":"〜からして","explanationKo":"문맥상 〜부터가; 〜만 보아도를 나타내는 「〜からして」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-06','reading',1,'翻訳で失われる前提','{"passage":"異なる言語の間で情報を伝えることには、知識や経験を広い相手と共有できることという利点がある。もっとも、単語を対応させるだけでは制度や文化の前提が抜けることには十分注意しなければならない。結論を急ぐのではなく、対象と前提を明らかにし、異なる条件でも判断が成り立つかを確かめる必要がある。したがって、用語の背景と適用範囲を具体例とともに示すことが重要なのである。","questions":[{"prompt":"「翻訳で失われる前提」について筆者が最も重視していることは何か。","options":["用語の背景と適用範囲を具体例とともに示すこと","最初の結論を変更しないこと","前提を示さず結果だけを伝えること","異なる条件を検討から外すこと"],"answer":"用語の背景と適用範囲を具体例とともに示すこと","explanationKo":"본문에서는 用語の背景と適用範囲を具体例とともに示すこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["単語を対応させるだけでは制度や文化の前提が抜けること","対象を明らかにすると利点が失われること","条件を比較すると結論を出せなくなること","記録を残せば必ず誤りが増えること"],"answer":"単語を対応させるだけでは制度や文化の前提が抜けること","explanationKo":"주의할 점은 単語を対応させるだけでは制度や文化の前提が抜けること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["知識や経験を広い相手と共有できること","前提は確認せずに判断すべきだ","結果が出た後の見直しは不要だ","一つの条件だけで結論を固定すべきだ"],"answer":"知識や経験を広い相手と共有できること","explanationKo":"異なる言語の間で情報を伝えること에는 知識や経験を広い相手と共有できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
